/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/yi.json — nu edita de mână */
__hubApps("yi",{"FreeDetect":{"line":"וויל איר קאָנטראָלירן צי אַ טעקסט איז געשריבן דורך קינסטלעכע אינטעליגענץ אָדער קאָפּירט? 42 דרויסנדיקע געצייגן און אַ ציטירונג־גענערייטאָר אין איין אָרט. די אַפּליקאַציע אַלײן דעטעקטירט גאָרנישט.","detail":"אַ טאַוולע פֿון 42 דרויסנדיקע AI־ און פּלאַגיאַט־דעטעקציע־געצייגן און אַ ציטירונג־גענערייטאָר (באַשטעטיקט ISBN). עס דעטעקטירט גאָרנישט לאָקאַל; עס העלפֿט בײַם קאָנטראָלירן פֿון רעפֿערענצן.","tags":["קאַטאַלאָג","ציטאַטן"]},"Arhiva-fara-frontiere":{"line":"דורכקוקט די זאַמלונגען פֿון Internet Archive אָן קאָנטאָ: זוך, זײַטלעך פֿון מאַטעריאַלן, פֿאָרויסשויונג און באַליבטע. נישט אָפֿיציעל; archive.org זעט אײַער IP און זוכענישן.","detail":"אומאָפֿיציעלער בראַוזער פֿאַר די זאַמלונגען פֿון Internet Archive (זוך, זײַטלעך פֿון מאַטעריאַלן, פֿאָרויסשויונג, באַליבטע און לעצטע זוכענישן, לאָקאַל געהיטן), אָן קאָנטאָ. ער זוכט נישט אין דער Wayback Machine; archive.org באַקומט אײַער IP און אײַערע זוכענישן.","tags":["וועב־אַרכיוון","קוואַלן"]},"AcademiSearch":{"line":"איין זוך פֿאַר וויסנשאַפֿטלעכע אַרטיקלען פֿון צענדליקער אָפֿענע קוואַלן. איר קענט היטן די רשימה פֿאַר ציטירן. דאַרף אינטערנעץ; די פֿרעגן גײען צו יענע סערוויסן.","detail":"אַקאַדעמישע מעטאַ־זוך איבער 11 אָפֿענע API (OpenAlex, Crossref, arXiv אאַז״וו) פּלוס לינקס צו פּאָרטאַלן; עקספּאָרט אין BibTeX/RIS/CSV. דאַרף אינטערנעץ; אײַערע פֿרעגן גײען צו יענע סערוויסן.","tags":["ליטעראַטור","קוואַלן"]},"Surveyor":{"line":"וואָסערע לינקס האָט אײַער זײַט, און וועלכע פֿונקציאָנירן נישט? ליסטעט זיי מיט אַנקערס און ווײַטערפֿירונגען. דרויסנדיקע קען מען נישט פֿאַרלעסלעך קאָנטראָלירן. נאָר פֿאַר אײַערע אײגענע זײַטן.","detail":"מאַכט אַן אינווענטאַר פֿון די לינקס פֿון אַ זײַט (סטאַטישער HTML, ענגליש אינטערפֿייס), אײַנשליסנדיק אַנקערס און ווײַטערפֿירונגען. דרויסנדיקע לינקס קען מען נישט באַשטעטיקן פֿון דעם בראַוזער (CORS); ער שיקט בקשות; קאָנטראָלירט נאָר אײַערע אײגענע זײַטן.","tags":["טויטע לינקס","אויעדיט"]},"Trade-Free-Link-Guardian":{"line":"פֿאַר אײַער WordPress־זײַט: געפֿינט צעבראָכענע לינקס און פֿאַרריכט זיי אָן דרויסנדיקע סערוויסן. ענדערט אמתן אינהאַלט, דעריבער מאַכט פֿריִער אַ באַקאַפּ. נישט געטעסט אין אַ ריאַלן WordPress.","detail":"WordPress־פּלאַגין וואָס קאָנטראָלירט לינקס און פֿאַרריכט צעבראָכענע אויף אַ דעטערמיניסטישן אופֿן, אָן דרויסנדיקן סערוויס. ער ענדערט אמתן אינהאַלט: מאַכט אַ באַקאַפּ. נישט געטעסט אויף אַ ריאַלן WordPress.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"היט אָפּ אײַערע זײַטן און זעט צי זיי ענטפֿערן נאָך. אַרבעט נאָר ביז דער טאַב איז אָפֿן. אַ טעותדיקע זײַט ציילט אויך ווי אַן ענטפֿער. די ווײַזונג איז ענגליש.","detail":"מאָניטאָר אין בראַוזער פֿאַר דערגרייכבאַרקייט: קאָנטראָלירט צי אײַערע זײַטן ענטפֿערן (ער לייענט נישט דעם HTTP־סטאַטוס־קאָד; 404/500 ציילן ווי אַן ענטפֿער). נאָר בעת דער טאַב איז אָפֿן. ענגלישער אינטערפֿייס.","tags":["מאָניטאָרינג"]},"ScryVeil":{"line":"קאָנטראָלירט די זיכערקייט פֿון אַ דאָמען און קריגט אַ טעקסט־באַריכט צו היטן. עטלעכע קאָנטראָלן קענען זײַן אומפֿולשטענדיק אָדער פֿאָדערן אַ שליסל. פֿאַרבינדט זיך מיט דריטע־צד סערוויסן; נאָר פֿאַר אײַערע דאָמענען.","detail":"זיכערקייט־דיאַגנאָזע פֿאַר אַ דאָמען (DNS, RDAP, סערטיפֿיקאַטן), מיט אַן עקספּאָרטירבאַרן טעקסט־באַריכט; קאָנטראָלן פֿון כעדערס און שום זענען אָפֿט בלאָקירט אָדער פֿאָדערן אַ שליסל. קאָנטאַקטירט דריטע־צד־סערוויסן; נאָר פֿאַר דאָמענען וואָס געהערן אײַך.","tags":["OSINT","זיכערקייט"]},"Vitrina":{"line":"באַשטעטיקט אַ עפֿנטלעכן Facebook־פּאָסט אין אײַער זײַט אָן קאָנטאָ און קאָפּירט דעם גרייטן קאָד. נישט אָפֿיציעל; Meta זעט אײַער IP, די ווײַזונג איז נישט געגאַראַנטירט.","detail":"באַשטעטיקט עפֿנטלעכע Facebook־זײַטן/פּאָסטן דורך Meta־פּלאַגינס, אומאָפֿיציעל; קאָפּירט דעם אײַנבעט־קאָד. „אָן קאָנטאָ“ מיינט נישט „אָן נאָכפֿאָלגן“: Meta זעט אײַער IP; די ווײַזונג איז נישט געגאַראַנטירט.","tags":["הינטער סטרימס"]},"Threads-fara-cont":{"line":"לייענט עפֿנטלעכע Threads־פּאָסטן אָן קאָנטאָ און היט זיי ווי טעקסט. נישט אָפֿיציעל; Meta זעט אײַער IP, מאָנכמאָל דאַרף מען אַ מיטלמאַן.","detail":"ווײַזט עפֿנטלעכע Threads־פּאָסטן דורך דעם Meta־אײַנבעט, אָן קאָנטאָ; אַפּציאָנעלע לאָקאַלע היטונג, עקספּאָרט אין .txt. Meta זעט אײַער IP; קען פֿאָדערן אַ CORS־פּראָקסי. אומאָפֿיציעל.","tags":["הינטער סטרימס"]},"X-fara-cont":{"line":"קומט צו עפֿנטלעכע פּראָפֿילן און פּאָסטן אויף X אָן קאָנטאָ אויף עטלעכע אופֿנים: דירעקטע לינק, אַרכיוו, זוך אָדער Nitter. לייענט נישט דעם אינהאַלט; שיקט די לינק צו archive.org.","detail":"גענערירט וועגן צו עפֿנטלעכע X־פּראָפֿילן און פּאָסטן אָן קאָנטאָ: דירעקטער לינק, Wayback־אַרכיוו, זוך, Nitter. ער לייענט נישט דעם אינהאַלט; שיקט דעם באַניצער־נאָמען/לינק צו archive.org.","tags":["הינטער סטרימס"]},"Arhiva-LinkedIn":{"line":"היט אין איין אָרט נאָטיצן וועגן LinkedIn־פּאָסטן וואָס איר האָט אַליין אײַנגעשטעלט און עקספּאָרטירט ווי טעקסט. די גאַלעריע נוצט אַן אָפֿיציעלע אײַנבעטונג, דעריבער פֿאַרבינדט זי זיך מיט LinkedIn. נישט אָפֿיציעל.","detail":"אַרכיוו פֿון נאָטיצן איבער LinkedIn־פּאָסטן וואָס מען קלעפּט אײַן מאַנועל (CSV־אימפּאָרט, Markdown־עקספּאָרט) + אַ גאַלעריע דורך דעם אָפֿיציעלן LinkedIn־אײַנבעט (קאָנטאַקטירט LinkedIn). אומאָפֿיציעל.","tags":["אַרכיוויזירן"]},"Cadraj":{"line":"זאַמלט TikTok־קליפּן מיט האַנט, גרופּירט לויט מחבר, און קוקט מיט דעם אָפֿיציעלן שפּילער. איר קענט צייכענען די שוין געזען.","detail":"מאַנועלע זאַמלונג פֿון TikTok־קליפּס לויט מחבר, אָפּגעשפּילט דורך דעם אָפֿיציעלן פּלייער; „געזען“־צייכן.","tags":["הינטער סטרימס"]},"FASCICUL":{"line":"פֿאַרוואַנדלט די טעלעפֿאָנען אין צימער אין אַ געמיינזאַמע טאָוול אויף אַ פּראָיעקטאָר: ציינונגען, נאָטיצן, בילדער, לאַזער־ווײַזער און לעבעדיקע קאַמערע. געטעסט מיט קאָמפּיוטער; מיט ריאַלע טעלעפֿאָנען נאָך נישט באַשטעטיקט.","detail":"טעלעפֿאָנען ↔ וידעאָ־פּראָיעקטאָר: אַ געמיינזאַמע טאַוולע מיט צייכענען, נאָטיצן, בילדער, לאַזער־ווײַזער און לעבעדיקער קאַמעראַ, אין איין טעקע. דירעקטע WebRTC־פֿאַרבינדונג אין דעם לאָקאַלן נעץ, אָן דריט־צד־סערווער; אַפּציאָנעלער רעלע אויפֿן האָטספּאָט־טעלעפֿאָן (Android/Termux). געטעסט אין Chromium; נאָך נישט באַשטעטיקט אויף ריאַלע טעלעפֿאָנען.","tags":["צוזאַמענאַרבעט"]},"INDICATIV":{"line":"גרייט זיך צו דער ANCOM־ראַדיאָ־ליבהאָבער־פּרוּוו אָן אינטערנעץ: 723 פֿראַגעס מיט איבערחזרונג. נישט אָפֿיציעל; די פֿראַגע־באַנק איז נאָר טיילווײַז קאָנטראָלירט.","detail":"אָפֿליין, אומאָפֿיציעלער טרענער פֿאַר דער ANCOM־עקזאַמען פֿאַר ליבהאָבער־ראַדיאָ (723 פֿראַגעס, ווידערהאָלונג מיט אינטערוואַלן, זוך אין דער פֿראַגע־באַנק). נישט קיין ANCOM־מאַטעריאַל; די פֿראַגע־באַנק איז נאָר טיילווײַז באַשטעטיקט.","tags":["עקזאַמען","ראַדיאָ"]},"ETER":{"line":"לערנט ראַדיאָ־ליבהאָבערײַ אין אַן ענציקלאָפּעדיע: מאָרזע־אַלפֿאַבעט, טרענער, אַנטענע־רעכענער און זוך איבער דעם גאַנצן אינהאַלט.","detail":"ענציקלאָפּעדיע פֿון ליבהאָבער־ראַדיאָ: מאָרזע, Koch־טרענער, אַנטענע־רעכענער, גלאָבאַלע זוך.","tags":["ראַדיאָ","ענציקלאָפּעדיע"]},"ATINGERE":{"line":"פֿאַרוואַנדלט אַ בוך אין בריִיל מיט וויבראַציעס פֿון טאַטש־עקראַן פֿאַר טויב־בלינדע, אָדער אין אַ הערבוך פֿאַר בלינדע. נישט געטעסט מיט בריִיל־לייענערס; האָט באַגרענעצונגען.","detail":"קאָנווערטירט ביכער אין טאַקטיל בראַיל אָדער אין אַודיאָביכער. נישט באַשטעטיקט מיט געבוירענע לייענער; זעט די באַגרענעצונגען אין דער README.","tags":["צוגענגלעכקייט"]},"Clopotel":{"line":"היט די צײַט אויף אַ קאָנפֿערענץ אָדער וואַרשטאַט: אַ בינע־טײַמער מיט אײַער פּראָגראַם און אַ סיגנאַל ווען דער סוף נענטערט זיך. ראָמעניש און ענגליש.","detail":"בינע־טײַמער מיט אַ רעדנער־אַגענדע (טעקסט־/CSV־אימפּאָרט) און אַ ווארענונג־סיגנאַל, RO/EN.","tags":["געשעענישן","MIT"]},"Monstrarium":{"line":"פּלאַנט אַ וואַרשטאַט פֿאַר מאַכן פֿון ראָסטערס פֿון איבערגעאַרבעטע מאַטעריאַלן: די אַפּליקאַציע רעכנט מאַטעריאַלן און סעסיעס, שלאָגט 50 ראָסטערס פֿאָר מיט קלאַנג, 3D און אַ לערן־שפּיל.","detail":"פּלאַנער פֿאַר אַן אַטעליע פֿון מאָנסטערס פֿון ריסײַקלירטע מאַטעריאַלן: רעכנט אַליין אויס די מאַטעריאַלן, צײַטפּלאַן לויט סעריעס, 50 אָריגינעלע מאָנסטערס מיט קולות, 3D און אַן דערציִונגס־שפּיל.","tags":["וואַרשטאַט","MIT"]},"TranslateHub":{"line":"קלײַבט פֿון 22 איבערזעצונג־געצייגן אָדער זעצט איבער מיט קינסטלעכער אינטעליגענץ מיט אײַער אײגענעם שליסל. דער טעקסט גייט צום Anthropic־סערוויס.","detail":"פֿאַרצייכענונג פֿון 22 איבערזעצונג־געצייגן פּלוס אַן AI־איבערזעצער מיט אײַער אייגענעם שליסל. AI־טעקסט ווערט געשיקט צו api.anthropic.com.","tags":["איבערזעצונג","AI"]},"DataWeave":{"line":"עפֿנט אַ טאַבעלע און פֿאַרשטייט זי: סטאַטיסטיק, גראַפֿיקס, פּיוואָט־טאַבעלעס און קאָרעלאַציעס. אײַערע דאַטן בלײַבן אויף אײַער מכשיר.","detail":"ויסשפּאַר CSV/TSV/JSON אין איין טעקע: טאַבעלע, סטאַטיסטיק, דיאַגראַמען, פּיוואָט און קאָרעלאַציעס; אײַערע דאַטן בלײַבן אויף אײַער מכשיר.","tags":["דאַטן"]},"MarkdownAtelier":{"line":"שרײַבט דאָקומענטן אין Markdown און זעט תּיכּף ווי זיי זעען אויס, מיט פּשוטע פֿאָרמלען: 7 שפּראַכן, אָן אינטערנעץ. די טעקסטן בלײַבן אין אײַער בראַוזער; מאַכט אַ באַקאַפּ.","detail":"אָפֿליין Markdown־רעדאַקטאָר מיט פֿאָרויסשויונג, GFM, אַ LaTeX־אונטערגרופּע (MathML), 7 שפּראַכן, זוך און .json־באַקאַפּ. דאָקומענטן בלײַבן אין בראַוזער.","tags":["שרײַבן"]},"RegexLab":{"line":"פּרוּווט אַ רעגולערן אויסדרוק און זעט תּיכּף וואָס ער כאַפּט: דערקלערונגען שריט פֿאַר שריט, טעסטן און אַ ווארענונג ווען ער קען פֿאַרפֿרירן דעם פּראָגראַם.","detail":"טעסטן פֿון JavaScript רעגולערע אויסדרוקן מיט דערקלערונגען, טעסטס און אַ ReDoS־ווארענונג.","tags":["אַנטוויקלונג"]},"SEOptimum":{"line":"קאָנטראָלירט ווי גרייט אַ וועב־זײַט איז פֿאַר זוך־מאָטאָרן. 20 געצייגן מיט אַנאַליז פֿון דער זײַט און פֿאָרויסשויונג ווי זי זעט אויס אין די זוך־רעזולטאַטן.","detail":"20 SEO־געצייגן אין בראַוזער: אָנאַליז פֿון דער זײַט, SERP־פֿאָרויסשויונגען.","tags":["וועב"]},"SEVA":{"line":"לערנט וועגן שלאָף, דעם טעגלעכן קערפּער־ריטם, אָטעמען און עסן אין אַן ענציקלאָפּעדיע וואָס מען קען אויך הערן. נאָר אינפֿאָרמאַציע; נישט קיין מעדיציניש עצה.","detail":"ענציקלאָפּעדיע פֿון געזונט־וווילזײַן: שלאָף, צירקאַדישער ריטם, אָטעמען, ערנערונג; צוהערן מיט פֿאָרלייענען. אינפֿאָרמאַטיוו; נישט קיין מעדיצינישער עצה.","tags":["געזונט"]},"PULS":{"line":"וואָס טוט מען ביז די ראַטעווע קומט? ראָמענישער ערשטע־הילף גיידבוך מיט אַ מעטראָנאָם פֿאַר ריפּאָנטירונג און אַן אָפּציאָנעלער נויטקאַרטע. קלינישע נישט קאָנטראָלירט; רופֿט 112.","detail":"ערשטע־הילף־פֿירער אויף רומעניש (CPR מיט מעטראָנאָם, טורניקעט), מיט זוך און אַן אַפּציאָנעלער נויטפֿאַל־קאַרטל. אינהאַלט נישט קלינישע באַשטעטיקט דורך אַ מומחה; פֿאַרבייט נישט קיין אויטאָריזירטן קורס. אין אַ נויטפֿאַל רופֿט 112.","tags":["געזונט","נויטפֿאַל"]},"VATRA":{"line":"וואָס טוט מען ווען וואַסער, פֿײַער אָדער באַשיצונג פֿעלן אין דער נאַטור? אָווערלעבן־ענציקלאָפּעדיע אָן אינטערנעץ מיט זוך און נאָטיצן. נאָר פֿאַר לערנען; אין נויטפֿאַל רופֿט 112.","detail":"אָפֿליין ענציקלאָפּעדיע פֿון איבערלעבונג (וואַסער, פֿייער, באַשיצונג, נאַוויגאַציע), מיט זוך און לאָקאַל געהיטענע נאָטיצן. דערציִונגס־מאַטעריאַל, פֿאַרבייט נישט קיין ערשטע־הילף־קורס; אין אַ נויטפֿאַל רופֿט 112.","tags":["פֿעלדאַרבעט"]},"Eclipsa-2027":{"line":"זעט אויף אַ מאַפּע אָן אינטערנעץ וווּ און ווי לאַנג דער גאַנצער זון־פֿינצטערניש פֿון 2 אויגוסט 2027 וועט דויערן, מיט שטעט און אָרט־זוך. די ווערטן זענען בערך; קוקט נישט אויף דער זון אָן אַ פֿילטער.","detail":"אָפֿליין מאַפּע פֿון דער גאַנצער זונפֿינצטערניש פֿון 2 אויגוסט 2027, מיט דויערן, דעקונג לויט שטאָט און זוך פֿון ערטער. אָנווײַזנדיקע ווערטן; קוקט נישט אויף דער זון אָן סערטיפֿיצירטע פֿילטערס.","tags":["אַסטראָנאָמיע"]},"orarium":{"line":"וואָס איז די צײַט איצט אויף מאַרס, אויפֿן לבֿנה אָדער אויף אַן אַסטעראָיד? לעבעדיקע ערטלעכע צײַט פֿאַר 45 הימלישע קערפּערס. בערך מאָדעל, אָן אינטערנעץ; נישט פֿאַר נאַוויגאַציע.","detail":"צײַט אויף יעדער וועלט: לעבעדיקע לאָקאַלע צײַט אויף 45 קערפּערס (לבֿנה, מאַרס, פּלאַנעטן, לבֿנות, אַסטערוידן), גיכקייט פֿון דער זייגער קעגן דער ערד, ווײַטקייט און צײַט פֿון אַהין־און־צוריק, אַ צײַט־זאָנע־קאָנווערטער און קאָלאָניזאַציע־מאַפּעס. אָנווײַזנדיקער מאָדעל, אָפֿליין; נישט פֿאַר נאַוויגאַציע. שליסט אײַן האַלבע נאַכט און האַלבן טאָג אויף יעדן קערפּער, טראַנסמיסיע־פֿענצטער ערד–קערפּער און אַ לינק צו TerRa.","tags":["אַסטראָנאָמיע","צײַט"]},"TerRa":{"line":"3D גלאָבוס און מאַפּע וואָס ווײַזן טאָג און נאַכט אויף דער ערד, דעם לבֿנה און די פּלאַנעטן. די שטעלעס פֿון סאַטעליטן קענען פֿאַרשפּעטיקן אַרום 3 חדשים ביז איר דערנײַערט אָנליין.","detail":"3D גלאָבוס און מאַפּע: טערמינאַטאָר, לבֿנה, פּלאַנעטן. סאַטעליטן ניצן אָפֿליין אַן אַלטן אָפּדרוק (~3 חדשים); פֿאַר איצטיקע פּאָזיציעס דערהײַנטיקט אָנליין. אײנציקער לינק פֿאַר יעדן בליק; דער הימל פֿון יעדן פֿון די 45 ORARIUM־קערפּערס, פֿאַרבונדן אין ביידע ריכטונגען.","tags":["אַסטראָנאָמיע"]},"Horizons.BeyondLimits":{"line":"פֿאָרט דורך דער געשיכטע פֿון אוניווערס פֿון דעם גרויסן קנאַל ביזן סוף מיט 91 וויכטיקע געשעענישן. די צוקונפֿט איז וויסנשאַפֿטלעכע השערה, נישט אַן גענויע פּראָגנאָז.","detail":"צײַט־מאַפּע פֿון דעם גרויסן קנאַל ביזן סוף פֿון דעם אַלוועלט: 91 געשעענישן, Markdown־עקספּאָרט; די צוקונפֿט איז ספּעקולאַטיוו, נישט קיין באַשטעטיקטע פּראָגנאָז.","tags":["קאָסמאָלאָגיע"]},"Hyper4D":{"line":"זעט ווי פֿיר־דימענסיאָנעלע פֿאָרמען זעען אויס: דרייט זיי אויפֿן עקראַן און קוקט פֿון עטלעכע ווינקלען. די בילדער קען מען היטן.","detail":"4D־געאָמעטריע אין SVG: 3D־שניטן פֿון 4D־קערפּערס און פּאָליטאָפּן מיט 4D→3D→2D־פּראָיעקציעס וואָס דרייען זיך אין ריאַל־צײַט, SVG־עקספּאָרט.","tags":["מאַטעמאַטיק"]},"ExploratoriiEco":{"line":"פֿעלד־גיידבוך פֿאַר נאַטור־ליבהאָבער: פֿון קלאַסיפֿיקאַציע פֿון לעבעדיקע וועזנס און שפּורן ביז ראָמעניע׳ס ביאָמען, אַ טאָגבוך פֿון אָבסערוואַציעס, עטיק און נויטפֿאַלן.","detail":"פֿעלד־פֿירער פֿאַר נאַטורפֿאָרשער אין 20 אָפּטיילן: קלאַסיפֿיקאַציע פֿון לעבן, סימנים און שפּורן, רומענישע ביאָמען, רעכענער, לאָגבוך, עטיק, נויטפֿאַלן און גלאָסאַר.","tags":["נאַטור"]},"FieldObserver":{"line":"צייכנט אײַערע פֿעלד־אָבסערוואַציעס; די ווערטן פֿון די סענסאָרן פֿון אײַער טעלעפֿאָן ווערן צוגעגעבן אויטאָמאַטיש. איר פֿירט אַן אַרכיוו פֿון אײַערע אויסגאַנגען.","detail":"פֿעלד־אָבסערוואַציע־לאָגבוך מיט די סענסאָרן פֿון טעלעפֿאָן; אַרכיוו, JSON/CSV־עקספּאָרט.","tags":["פֿעלדאַרבעט"]},"VietAR":{"line":"פֿאָטאָגראַפֿירט אָדער רעקאָרדירט אַ פּלאַנץ אָדער באַשעפֿעניש און קריגט אַן אָנווייַזונג צווישן 519 מינים פֿון ראָמעניע. קען זיך טועה זײַן; עסט גאָרנישט דערפֿון.","detail":"אָנווײַזנדיקע אידענטיפֿיצירונג פֿון 519 רומענישע מינים לויט בילד/קול; קען זײַן פֿאַלש, עסט נישט קיין געוויקסן אָדער שוועמלעך לויט דעם. מאָדעלן ווערן אַראָפּגעלאָדן פֿון דריטע צדדים; נישט גאָר אָפֿליין.","tags":["ביאָדיווערסיטעט"]},"VOIAJOR":{"line":"פֿאָלגט נאָך די וועגן פֿון וויאָדזשער 1 און 2 פֿון 1977 ביז אַ מיליאַרד יאָר שפּעטער אין יעדער מאַסשטאַב: פֿון פּלאַנעטן ביזן מילכוועג. בערך מאָדעל, נישט פֿאַר נאַוויגאַציע.","detail":"סימולאַציע פֿון די טראַיעקטאָריעס פֿון Voyager 1 און 2 (1977 ביז איבער אַ ביליאָן יאָר): באַליסטישע בויגנס צווישן די ריאַלע פֿאַרבײַפֿליִען, עקסטראַפּאָלאַציע מיט זון־גראַוויטאַציע און לאָקאַלער גאַלאַקטישער דינאַמיק, די העליאָספֿער, דער Oort־וואָלקן און 19 נאָענטע שטערן מיט אייגענער באַוועגונג.","tags":["וויאָדזשער","סימולאַציע"]},"Nemurirea":{"line":"דערגייט ווי דער קערפּער װערט אַלט און וואָס די וויסנשאַפֿט זאָגט וועגן ביאָלאָגישע זייגערס און לאַנגלעביקייט, דערנאָך פּרוּווט זיך אַליין מיט אַ טעסט. נישט קיין מעדיציניש עצה.","detail":"אינטעראַקטיווער עסיי וועגן ביאָלאָגישע זייגערס און דער וויסנשאַפֿט פֿון לאַנגלעבעדיקייט, מיט אַ לעצטן קוויז. אינפֿאָרמאַטיוו צוועק, נישט קיין מעדיצינישער עצה.","tags":["ביאָלאָגיע"]},"IncredibleCosmos":{"line":"שטעלט פּלאַנעטן און שטערן אַזוי אַז זייער ציִונג פֿירט דעם קאָמעט צום ציל. 108 לעוולען, דרײַ שװעריקייטן און ביז דרײַ שטערן פּער לעוועל.","detail":"גראַוויטאַציע־רעטעניש: שטעלט פּלאַנעטן און שטערן אַזוי אַז זייער גראַוויטאַציע פֿירט אַ קאָמעט צום ציל; 108 מדרגות אין 12 קאַטעגאָריעס, דרײַ שווערקייטן, 1–3־שטערן־אָפּשאַצונג, מיט זוך.","tags":["שפּיל","פֿיזיק"]},"Cupa-Mondiala-2026":{"line":"שפּילט אין דער וועלט־טורניר פֿון 2026 און פֿאָלגט אָפּ דעם גאַנג פֿון אַן אויסגעטראַכט טורניר. די רעזולטאַטן זענען געלעגנהייט, נישט קיין פּראָגנאָז; נישט אָפֿיציעל.","detail":"פֿיקטיווער, אומאָפֿיציעלער סימולאַטאָר פֿון דער וועלט־מײַסטערשאַפֿט 2026: טראַפֿעוודיקע רעזולטאַטן, נישט קיין פּראָגנאָזן; נישט פֿאַרבונדן מיט FIFA.","tags":["סימולאַציע","נישט אָפֿיציעל"]},"AGORA":{"line":"ווי דער עוראָ איז געבוירן געוואָרן און וואָס ער מיינט פֿאַר ראָמעניע. 59 קאַפּיטלען פֿון מאַסטריכט ביזן EZB, און עצות פֿאַר רײַזנדע. נישט אָפֿיציעל.","detail":"אינפֿאָרמאַטיווער אַטלאַס פֿון דער אײַראָ־זאָנע אין 59 אָפּטיילן: פֿון Maastricht און דער ECB ביז רומעניע און דעם אײַראָ, פּלוס אַ רײַזע־פֿירער. אומאָפֿיציעל, אָן יורידישן ווערט.","tags":["עקאָנאָמיע","EU"]},"URME":{"line":"גרייט זיך צו אַ װאַנדערונג אויפֿן Colți–Aluniș־שטעג אין בוזעו: געוויקסן, בורשטין, פֿאָסילן, צײַטן פֿון זונאויפֿגאַנג און זונאונטערגאַנג, אויסריכטונג. די מאַפּע איז נישט פֿאַר נאַוויגאַציע.","detail":"אינפֿאָרמאַטיווער, אומאָפֿיציעלער װאַנדער־פֿירער פֿאַר Colți–Aluniș (געוויקסן, בורשטין, פֿאָסילן), מיט זונאויפֿגאַנג/זונפֿאַרגאַנג און אַ רשימה פֿון אויסרוסטונג. סכעמאַטישע מאַפּע, נישט פֿאַר נאַוויגאַציע; אַרויסנעמען פֿון דעם באַשיצטן געביט איז פֿאַרבאָטן.","tags":["נאַטור","בוזעו"]},"Belot-fara-frontiere":{"line":"לערנט קענען בעלאָט און זײַנע קרובֿים אין אַנדערע לענדער, דערנאָך שפּילט אַרום דעם טיש: איר און אַ AI־פּאַרטנער קעגן צוויי AI־קעגנער. מיט אַ פּונקט־בלאָק.","detail":"אַטלאַס פֿון דער משפּחה belote/bela/klaverjas/jass און אַ שפּיל פֿאַר 4 שפּילער (איר און אַן AI־פּאַרטנער קעגן צוויי AI־קעגנער); דער רומענישער belot איז די פּרייאָריטעט; נקודות־בלאַט.","tags":["קאַרטן־שפּילן","AI"]},"Scopone-fara-frontiere":{"line":"דערגייט ווי סקאָפּאָנע איז געבוירן געוואָרן, וואָס פֿאַר כּללים עס האָט און ווי זיי ענדערן זיך פֿון געגנט צו געגנט, דערנאָך שפּילט קעגן אַ קאָמפּיוטער וואָס קען ראָטן.","detail":"Scopone־אַטלאַס (15 בלעטער: אָפּשטאַם, כּללים, רעגיאָנאַלע אונטערשיידן) און אַ שפּיל קעגן אַ לאָקאַלן AI (העוריסטיש / Monte-Carlo), מיט עצות; איטאַליענישע אָדער פֿראַנצויזישע קאָלירן.","tags":["קאַרטן־שפּילן","AI"]},"Solitaire-fara-frontiere":{"line":"קוקט און שפּילט סאָליטערס ווי Klondike, FreeCell אָדער Spider. ווען איר זענט פֿאַרשטעקט, בעט אַ הינט אָדער לאָזט דעם קאָמפּיוטער לײזן.","detail":"אַטלאַס פֿון סאָליטער־שפּילן (Klondike, FreeCell, Spider און אַנדערע) אויף אַ געמיינזאַמען מאָטאָר; „עצה“ פֿון אַ סאָלווער מיט אַ באַגרענעצונג אויף קנופּן/צײַט און אַפּציאָנעלער אויטאָ־לייזונג.","tags":["קאַרטן־שפּילן"]},"Sudoku-fara-frontiere":{"line":"136 סאָרטן סודאָקו, פֿון קלאַסיש ביז killer און 3D: קוקט און שפּילט. העלפֿט מיט דערקלערונגען שריט פֿאַר שריט און לייזט אײַערע אײגענע רעטענישן.","detail":"אַטלאַס פֿון 136 Sudoku־וואַריאַנטן (קלאַסיש, killer, jigsaw, גריכיש־לאַטײַניש, 3D און פֿיל מער), מיט אַ גענערייטאָר מיט אײנציקער לייזונג, דערקלערטער שריט־פֿאַר־שריט לייזונג, 7 שפּיל־אופֿנים און אַ סאָלווער.","tags":["רעטענישן"]},"Domino-fara-frontiere":{"line":"לערנט די געשיכטע און כּללים פֿון דאָמינאָ, דערנאָך שפּילט אַרום דעם טיש קעגן איינעם ביז דרײַ קאָמפּיוטער־קעגנער. אַ גאַנג קען מען אָפּשטעלן.","detail":"Domino־אַטלאַס (אָפּשטאַם, כּללים, אָפּשאַצונגען) און אַ שפּיל־טיש קעגן 1–3 AI־שפּילער, מיט דרײַ מדרגות; צוריקנעמען אַ צוג.","tags":["דאָמינאָ","AI"]},"Mahjong-fara-frontiere":{"line":"לערנט קענען 8 סאָרטן מאַדזשאָנג: שפּילט סאָליטער אָדער אַ שפּיל פֿאַר פֿיר מיט דרײַ פּשוטע קאָמפּיוטער־קעגנער. אַרבעט אָן אינטערנעץ.","detail":"אַטלאַס פֿון 8 mahjong־וואַריאַנטן, סאָליטער און mahjong פֿאַר 4 שפּילער (riichi, Hong Kong, Sichuan) קעגן 3 פּשוטע העוריסטישע AI. אָפֿליין.","tags":["מאַדזשאָנג","AI"]},"Go-fara-frontiere":{"line":"דערגייט פֿון וואַנען גאָ קומט און ווי מען שפּילט, דערנאָך פּרוּווט אײַערע כּוחות קעגן אַ קאָמפּיוטער וואָס קען ראָטן. שיקט קיין דאַטן איבערן אינטערנעץ.","detail":"Go־אַטלאַס (18 בלעטער: אָפּשטאַם, כּללים, אָפּשאַצונגען) און אַ שפּיל קעגן אַ לאָקאַלן AI (Monte-Carlo, נישט קיין LLM), מיט SGF און עצות; קיין נעץ־בקשות.","tags":["גאָ","AI"]},"Zaruri-fara-frontiere":{"line":"26 קוביה־שפּילן צום לייענען, 12 פֿון זיי קעגן אַ קאָמפּיוטער; אויך אַ סימולאַטאָר פֿון וואַרף מיט ווײַזונג פֿון מעגלעכקייטן. אָן געלט; אָפֿלײַן.","detail":"אַטלאַס פֿון 26 קוביה־שפּילן; 12 שפּילבאַר קעגן אַ דידאַקטישן AI (נישט קיין LLM), פּלוס אַן NdM־סימולאַטאָר מיט פּינקטלעכע מעגלעכקייטן. נישט קיין גליקשפּיל; אָפֿליין.","tags":["קוביות"]},"Sah-fara-frontiere":{"line":"איבער 700 סאָרטן שאַך צום לערנען און אַ קליין ווערטערבוך פֿון טערמינען; רובֿ קען מען שפּילן קעגן אַ קאָמפּיוטער. אַרבעט אָן אינטערנעץ.","detail":"706 אײַנטראָגן פֿון שאַך־וואַריאַנטן (נאָר עטלעכע מיט אַ באַשטעטיקטער קוואַל; עטלעכע סינטעטישע) און 299 לעקסיקאָן־טערמינען. אָפֿליין, מיט אַ לאָקאַלן מאָטאָר פֿאַר פֿיל וואַריאַנטן.","tags":["שאַך"]},"Dame-fara-frontiere":{"line":"שפּילט 25 סאָרטן שאַשקע קעגן אַ קאָמפּיוטער און היט די פּאַרטיע. די כּללים פֿון 16 פֿון זיי זענען נאָר בערך און מאַרקירט מיט ⚠.","detail":"25 דאַמע־וואַריאַנטן שפּילבאַר קעגן אַ דידאַקטישן AI, מיט שפּיל־עקספּאָרט; 16 האָבן אָפּגעשאַצטע כּללים (מאַרקירט ⚠).","tags":["שאַשקע"]},"Table-fara-frontiere":{"line":"טריק־טראַק, טאַוולע, נאַרד און ראָמענישע סאָרטן; לייענט און שפּילט: 17 סאָרטן קעגן אַ קאָמפּיוטער, מיט קלאַוויאַטור אָדער מויז.","detail":"שפּילבאַרער אַטלאַס פֿון דער באַקגעמאָן־משפּחה: backgammon, Tavli, Tavla, Narde, Gul Bara און רומענישע וואַריאַנטן; 17 וואַריאַנטן קעגן אַן אויסלערנענדן AI; שפּילן מיט דער קלאַוויאַטור.","tags":["טריק־טראַק"]},"Remi-fara-frontiere":{"line":"לערנט קענען די ראַמי־משפּחה און שפּילט 19 סאָרטן קעגן אַ קאָמפּיוטער, מיט סטאַטיסטיק. 8 שפּראַכן; גרויסע, לײַכט צו זען שטײנער אָדער קאַרטן.","detail":"אַטלאַס פֿון דער rummy־משפּחה פֿון שפּילן: 19 שפּילבאַרע וואַריאַנטן קעגן אַ לאָקאַלן AI, מיט סטאַטיסטיק; אינטערפֿייס אין 8 שפּראַכן, מיט גרויסע שטיינער און קאַרטן.","tags":["ראַמי"]},"Carti-de-joc-fara-frontiere":{"line":"פֿון סאָליטער און שוואַרצער פּעטער ביז פּאָקער: 17 קאַרטן־שפּילן מיט דערקלערטע כּללים, 8 פֿון זיי קענט איר תּיכּף שפּילן.","detail":"אינטעראַקטיווער אַטלאַס פֿון קאַרטן־שפּילן, פֿון סאָליטער און Old Maid ביז פּאָקער: 17 שפּילן מיט כּללים־בלעטער, 8 פֿון זיי שפּילבאַר.","tags":["קאַרטן־שפּילן"]},"Undava":{"line":"מאַכט אַ וויקטאָרינע אָדער שפּילט זי מיט פֿרײַנד אויף דעם זעלבן טעלעפֿאָן אָדער קאָמפּיוטער און שפּילט איבער די פֿראַגעס וואָס איר האָט טועה געווען. ווי Kahoot, אָבער אָן פֿאַרבינדונג.","detail":"Kahoot־סטיל קוויז (נישט פֿאַרבונדן), אין איין טעקע: סאָלאָ אָדער אַרומגעבן אויף דעם זעלבן מכשיר, מיט ווידערהאָלונג פֿון טעותים. לעבעדיקע שפּיל נאָר אין דער סערווער־אויסגאַבע.","tags":["וויקטאָרינע","בילדונג"]},"AI-Liber":{"line":"רעדט מיט עטלעכע קינסטלעכע־אינטעליגענץ העלפֿערס אין איין אָרט, עטלעכע אַרבעטן אויף אײַער קאָמפּיוטער. די אָנזאָגן גייען צום אָנבאַטער וואָס איר קלײַבט; AI קען טועה זײַן.","detail":"שמועס מיט עטלעכע AI־פּראָוויידערס, אַרײַנגערעכנט לאָקאַלע (Ollama, WebLLM). נאָכריכטן גײען צו דעם פּראָוויידער וואָס איר קלײַבט; AI־ענטפֿערס קענען זײַן פֿאַלש.","tags":["AI"]},"LocalMind":{"line":"רעדט מיט אַ קליינעם קינסטלעכע־אינטעליגענץ העלפֿער וואָס אַרבעט גלײַך אין אײַער בראַוזער. די מאָדעלן װערן אַראָפּגעלאָדן פֿון אינטערנעץ איין מאָל; קען טועה זײַן.","detail":"שמועס מיט קליינע מאָדעלן (Qwen3, LFM2) וואָס לויפֿן לאָקאַל אין בראַוזער (WebGPU). מאָדעלן קומען פֿון Hugging Face; קען זײַן פֿאַלש. דאַרף אַ לאָקאַלן סערווער אָדער די עפֿנטלעכע זײַט.","tags":["ערטלעכער AI"]},"PromptVault":{"line":"איבער 500 גרייטע פּראָמפּטן פֿאַר AI־העלפֿער; קלײַבט און צייכנט די באַליבטע. היט נישט אײַערע אײגענע טעקסטן.","detail":"ביבליאָטעק פֿון 500+ פּראָמפּטן מיט באַליבטע, נישט קיין פֿאַרוואַלטער פֿאַר אײַערע אייגענע פּראָמפּטן.","tags":["פּראָמפּטן"]},"ARENA":{"line":"לאָזט צוויי AI־מאָדעלן ענטפֿערן בלינד און שטימט פֿאַר דעם בעסערן; דער ראַנג בלײַבט אויף אײַער קאָמפּיוטער. דאַרף אײַערע אײגענע שליסלען.","detail":"בלינדע דועלן צווישן AI־מאָדעלן מיט אַ לאָקאַלן Elo־ראַנג (CSV־עקספּאָרט). דאַרף אײַערע אייגענע API־שליסלען אָדער לאָקאַלע סערווערס; די דעמאָ־מאָדעלן זענען סימולירט.","tags":["AI־אָפּשאַצונג"]},"Nexus-fara-frontiere":{"line":"רעדט מיט AI־העלפֿער פֿון עטלעכע אָנבאַטערס; שמועס מיט זוך און היטן. דאַרף אינטערנעץ און אײַערע אײגענע שליסלען, וואָס ווערן געהיט אָן פֿאַרשליסונג.","detail":"AI־שמועס־קליענט מיט אײַערע אייגענע API־שליסלען (Anthropic, OpenAI, Google, OpenAI־קאָמפּאַטיבל), מיט זוך און Markdown־עקספּאָרט; די „אַגענטן“ זענען פּראָמפּטן. דאַרף אינטערנעץ; שליסלען ווערן געהיט אומפֿאַרשלעסלט.","tags":["אַגענטן"]},"VoiceAtelier":{"line":"הערט ווי הונדערטער קינסטלעכע קולות קלינגען אין צענדליקער שפּראַכן און לערנט ווי מען מאַכט אַ הערבוך. דער אָנליין־מוסטער שיקט דעם טעקסט צו דרויסנדיקע סערוויסן נאָר מיט אײַער דערלויבעניש.","detail":"קאַטאַלאָג פֿון 427 נעוראַלע קולות (141 לאָקאַלן) און אַן אַודיאָבוך־פֿירער. דער אָנליין־מוסטער שיקט דעם טעקסט צו אַ רעלע און צו Microsoft, נאָר מיט אײַער הסכּמה. נישט קיין TTS־סטודיע.","tags":["קול"]},"Trusa-fara-frontiere":{"line":"אַ זאַמלונג פֿון 15 קליינע טעגלעכע געצייגן: נאָטיצן, טאַבעלע, Markdown, פּאַראָלן, פֿינאַנץ־טאָגבוך און נאָך. נישט אָפֿיציעל פֿאַרבונדן מיט YunoHost, וואָס האָט אײַנגעשפּירט די קאַטעגאָריעס.","detail":"אַ סעט פֿון 15 קליינע מאָדולן געשריבן פֿון אָנהייב (נאָטיצן, טאַבעלע, Markdown, פּאַסוואָרטן, פֿינאַנץ־לאָגבוך און מער), אינספּירירט פֿון די YunoHost־אַפּ־קאַטעגאָריעס; נישט פֿאַרבונדן.","tags":["געצייגן"]},"API-fara-frontiere":{"line":"וועטער, NASA־בילדער, שטעלע פֿון ISS און צענדליקער לעבעדיקע דאַטן אין איין אָרט. דאַרף אינטערנעץ; נישט געטעסט מיט ריאַלע סערוויסן.","detail":"52 ווידזשעטס: 47 איבער עפֿנטלעכע API (דאַרף אינטערנעץ; בײַם עפֿענען אָנליין קאָנטאַקטירט עס אויטאָמאַטיש Open-Meteo, NASA און ISS) און 5 לאָקאַלע ניצלעכקייטן. נישט געטעסט קעגן ריאַלע סערווערס.","tags":["API"]},"OmniHost":{"line":"אַ גרויס פּאַקעט פֿון איבער הונדערט אַרבעטס־געצייגן אין איין אָרט. פֿאַרבינדט זיך מיט פֿיר דרויסנדיקע סערוויסן; פּרטים אין README.","detail":"פּראָדוקטיוויטעט־סוויטע (~4 MB, 141 מאָדולן). קאָנטאַקטירט פֿיר דרויסנדיקע האָסטס; זעט די README.","tags":["פּאַקעט"]},"VNTV":{"line":"שפּילט VideoNeat־טרײַלערס ווי אַ קעסיקער טעלעוויזיע־קאַנאַל. דאַרף אינטערנעץ; אין P2P־רעזשים זעען אַנדערע צושויער אײַער אַדרעס.","detail":"VideoNeat־טרײלערס ווי אַ קאָנטינויִרלעך טעלעוויזיע־פּראָגראַם, פּלוס אַ Stremio־אַדאָן. דאַרף אינטערנעץ (videoneat.com, videos.trom.tf); אין P2P־אופֿן איז אײַער IP זעבאַר פֿאַר אַנדערע צוקוקער.","tags":["מעדיע","MIT"]},"OSATURA":{"line":"לעבעדיקט 2D־ציינונגען: פֿאַרבינדט זיי מיט אַ „סקעלעט“, שטעלט אין באַוועגונג און עקספּאָרטירט די אַנימאַציע אין עטלעכע פֿאָרמאַטן. אַלפֿאַ־ווערסיע, ביז איצט קוים געטעסט.","detail":"2D וועקטאָר־ריגינג־ און אַנימאַציע־מאָטאָר אין Rust (ביינער, IK, skinning, פֿיזיק, צושטאַנד־מאַשינען) מיט אַ בראַוזער־סטודיע און עקספּאָרט אין SVG, PNG, GIF, Lottie און glTF. נאַטיווע פּראָגראַם (באַפֿעל־שורה + סטודיע) און WebAssembly־מאָדול, נישט קיין איינציקע HTML־טעקע; אַלפֿאַ, ביז אַצונד ווײניק געפּרוּווט דורך באַניצער. ליצענצן: MPL-2.0 ביבליאָטעקן, AGPL-3.0-or-later CLI.","tags":["אַנימאַציע","MPL/AGPL"]},"OAZA":{"line":"340 פֿרײַע וועב־סערוויסן, מערסטנס אָן קאָנטאָ, אין איין קאַטאַלאָג. די רשימה איז קאָנטראָלירט אין יוני 2026, אָבער נישט אויטאָמאַטיש.","detail":"קאַטאַלאָג פֿון 340 פֿרײַע דריטע־צד־וועב־סערוויסן, געוויינטלעך באַניצבאַר אָן קאָנטאָ (נישט אויטאָמאַטיש באַשטעטיקט; קאָנטראָלירט יוני 2026).","tags":["סערוויסן"]},"VaultCrypt":{"line":"האָט איר עפּעס צו באַהאַלטן פֿון נײַגעריקע אויגן? פֿאַרשליסט טעקעס און טעקסטן מיט אַ פּאַראָל גלײַך אין בראַוזער. אַ פֿאַרלוירן פּאַראָל ווערט נישט צוריקגעשטעלט.","detail":"AES-256-GCM־פֿאַרשלעסלונג פֿון טעקעס און טעקסט אין בראַוזער. נישט אומאָפּהענגיק אויפֿגעפּרוּװט; אַ פֿאַרלוירן פּאַסוואָרט קען מען נישט צוריקבאַקומען.","tags":["זיכערקייט"]},"Akasha":{"line":"נאָטיצבוך וואָס אַרבעט אָפֿלײַן, מיט טאַגס, זוך און לינקס צווישן זײַטלעך. כּדי גאָרנישט זאָל נישט פֿאַרלוירן ווערן, לאָדט אַראָפּ אַן אַקטועלע קאָפּיע פֿון דער טעקע.","detail":"אָפֿליין נאָטיצן אין איין טעקע, מיט טאַגס, זוך און [[Title]]־לינקס; כּדי צו היטן אײַערע דאַטן לאָדט איר אַראָפּ אַ פֿריש קאָפּיע פֿון דער טעקע (quine).","tags":["נאָטיצן"]},"CLEPSIDRA":{"line":"אַ צוריקצײלנדיקער זייגער, וועקער און צײַט־פּלענער פֿאַר אַרבעטס־טעג און אָפּרוּ־טעג. פֿאָלגט נאָך יום־טובֿים און אײַערע אײגענע געשעענישן.","detail":"פֿאַרקערטער זייגער, וועקער, פּלענער פֿאַר וואָכנטאָג/וואָכנענד, יום־טובֿים, געשעענישן.","tags":["צײַט"]},"Origami":{"line":"לערנט פֿאַלדן פּאַפּיר שריט פֿאַר שריט: צייכנס, טעכניקן און אילוסטרירטע מאָדעלן. די אַפּליקאַציע געדענקט וווּ איר האָט זיך אָפּגעשטעלט.","detail":"אָריגאַמי־פֿירער: נאָטאַציע, טעכניקן, שריט־פֿאַר־שריט מאָדעלן, מיט פּראָגרעס לאָקאַל געהיטן.","tags":["קונסט"]},"Zicala":{"line":"יעדן טאָג איין ראָמעניש שפּריכוואָרט פֿון אַ זאַמלונג פֿון 550. איר קענט זוכן און היטן באַליבטע; די קאָמענטאַרן זענען געשריבן מיט AI־הילף.","detail":"550 רומענישע שפּריכווערטער מיט אַ שפּריכווארט פֿון טאָג, זוך און עקספּאָרט/אימפּאָרט פֿון באַליבטע; די SWOT/TOWS־קאָמענטאַרן זענען מיט AI־הילף.","tags":["קולטור"]},"Limpezimea":{"line":"לייענט דעם וויסנשאַפֿט־פֿאַנטאַזיע־ראָמאַן „Limpezimea“ אין זיבן שפּראַכן. די באַגלייטנדיקע כראָנאָלאָגיע און קריטישע שטודיע זענען געשריבן מיט AI־הילף (Claude).","detail":"דער SF־ראָמאַן „Limpezimea“ אין 7 שפּראַכן, לייען־אויסגאַבע. דער קריטישער אַפּאַראַט (כראָניק, שטודיע) איז געשריבן מיט AI־הילף (Claude).","tags":["ליטעראַטור"]},"Nota-Zero":{"line":"אַ ספּעקולאַטיווע פֿאַנטאַסטישע דערציילונג וועגן סטרונע־טעאָריע אויף ראָמעניש, ענגליש און פֿראַנצויזיש, מיט נאָטיצן וואָס דערקלערן די וויסנשאַפֿטלעכע אידעען. בעלעטריסטיק, נישט אַקאַדעמישע קוואַל.","detail":"ספּעקולאַטיווע פֿיקציע־דערציילונג וועגן סטרונע־טעאָריע, אויף רומעניש, ענגליש און פֿראַנצויזיש, מיט דערקלערנדיקע וויסנשאַפֿטלעכע נאָטיצן (פֿיקציע, נישט קיין אַקאַדעמישע קוואַל).","tags":["ליטעראַטור"]},"Pendulul":{"line":"אַ פּלאַנעט שוואַנקט צווישן דרײַ שטערן און אַ שוואַרצן לאָך: אַן ראָמאַן אין נײַן באַנדן, וואָס Alexio האָט געשריבן מיט Claude. 3D־סימולאַציע, לייענער מיט היטן אָפֿלײַן, EPUB און PDF.","detail":"ניין־בענדיקער SF־ראָמאַן פֿון Alexio, געשריבן מיט Claude: אַ פּלאַנעט שוינגט זיך צווישן דרײַ שטערן און אַ שוואַרצן לאָך. שליסט אײַן אַ 3D־סימולאַציע און דעם בוך־לייענער אין איין HTML־טעקע וואָס מען קען אָפּשפּײַכערן און לייענען אָפֿליין, פּלוס EPUB און PDF.","tags":["ליטעראַטור"]},"PrintreInteligente":{"line":"טרעט אַרײַן אין אַן אינטעראַקטיוון וויסנשאַפֿט־פֿאַנטאַזיע־ראָמאַן מיט העלדן אינספּירירט פֿון דער Artemis 2־מאַנשאַפֿט. די דערמאָנונגען זענען אויסגעטראַכט; איבערזעצונג, קול און AI־פֿונקציעס נוצן דרויסנדיקע סערוויסן.","detail":"אינטעראַקטיווער SF־ראָמאַן, פֿיקציע מיט פֿיגורן אינספּירירט פֿון דער Artemis 2־מאַנשאַפֿט; די רעצענזיעס זענען פֿיקטיווע. איבערזעצונג, אָנליין־קול און AI־פֿונקציעס ניצן דרויסנדיקע סערוויסן.","tags":["ליטעראַטור"]},"BorderlessMelodies":{"line":"הערט זיך אײַן אין אַ מוזיק וואָס שאַפֿט זיך אַליין גלײַך אין בראַוזער. איר קענט עקספּאָרטירן ווי אויַדיאָ; עס איז דאָ אַ שלאָף־טײַמער.","detail":"פּראָצעדוראַלע מוזיק אין Web Audio, מיט אַודיאָ־עקספּאָרט און שלאָף־טײַמער.","tags":["מוזיק"]},"EcoulSpectral":{"line":"זעט דעם קלאַנג ווי אַ בילד, קלײַבט דעם טייל וואָס שטערט און אָפּגעזונדערט אָדער ויסמעקט אים. כּולל רעש־רעדוצירונג, דעטעקציע פֿון קולות און היטן ווי WAV.","detail":"לאָקאַלער ספּעקטראָגראַם־רעדאַקטאָר: מאַרקירט אַ צײַט־פֿרעקווענץ־געגנט און איזאָלירט אָדער אַראָפּנעמט זי; שטימע־דעטעקציע, ראַש־רעדוקציע, WAV־עקספּאָרט.","tags":["אויַדיאָ"]},"Constelar":{"line":"רעדט מיט וויִרטועלע פֿרײַנד וואָס געדענקען אײַערע שמועסן. פֿון דעפֿאָלט ענטפֿערן זיי מיט פּשוטע כּללים; ריאַלער AI נאָר אויב איר קלײַבט אַן אָנבאַטער, און דעמאָלט גייען אײַערע אָנזאָגן צו אים. נאָר פֿאַר דערוואַקסענע.","detail":"שמועס־באַגלייטער מיט לאָקאַלער זכּרון. סטאַנדאַרטמעסיק אַ פּשוטער כּללים־באַזירטער מאָטאָר; אמתער AI נאָר אויב איר קלײַבט אַ פּראָוויידער (נאָכריכטן ווערן צו אים געשיקט). פֿאַר דערוואַקסענע; פֿאַרבייט נישט קיין טעראַפּיע.","tags":["AI"]},"Tarot":{"line":"דערגייט די געשיכטע פֿון טאַראָט, די סימבאָלן פֿון די קאַרטן און ווי מען לייענט זיי ווי אַ קולטורעלע דערשײַנונג. אינטעראַקטיווער קורס אין אײַער טעמפּאָ.","detail":"אינטעראַקטיווער קורס: די געשיכטע, סימבאָלן און לייענען פֿון די קאַרטן, ווי אַ קולטורעלע דערשײַנונג.","tags":["קולטור"]},"Numerologie":{"line":"דערגייט נומעראָלאָגיע ווי אַ סימבאָלישע טראַדיציע אויף פֿיר לעוולען, מיט געניטונגען, ווערטערבוך, טאָגבוך און רעכענער. געוויזן אָן וויסנשאַפֿטלעכער באַשטעטיקונג.","detail":"אינטעראַקטיווער קורס וועגן נומעראָלאָגיע ווי אַ סימבאָלישע טראַדיציע: פֿיר מדרגות, געניטונגען, גלאָסאַר, טאָגבוך און רעכענער; געשטעלט אָן וויסנשאַפֿטלעכער באַשטעטיקונג.","tags":["קולטור"]},"PUNCTUM":{"line":"לערן־אַטלאַס פֿון אַקופּרעסור און פּונקט־טעראַפּיעס: איבער 400 פּונקטן אויף אינטעראַקטיווע מאַפּעס, זעלבסט־זאָרג רעזשימען מיט געפֿירטע סעסיעס, באַווײַזן און זיכערקייט. פֿאַרבײַט נישט קיין דאָקטער.","detail":"אַ דערציִונגס־אַטלאַס פֿון פּונקט־באַזירטע טעראַפּיעס (אַקופּונקטור, אַקופּרעסור, מאָקסיבוסטיע, כּוסות, אָרן־טעראַפּיע, רעפֿלעקסאָלאָגיע און מער): 410 פּונקטן אויף 14 מעריִדיאַנען, 60 וואַריאַנטן מיט אַ באַווײַז־מדרגה, SVG־מאַפּעס, באַשעפֿענישן און רוטינעס, אַ קורס, אַ קוויז, קאַרטלעך און פּערזענלעכע זיכערקייט־קאָנטראָלן.","tags":["געזונט","באַווײַזן"]},"Reiki":{"line":"דערגייט וואָס רייקי איז, אַ גײַסטיקע פּראַקטיק, און וואָס די פֿאָרשונג זאָגט: אויסער רעלאַקסאַציע איז נישט געפֿונען גענוג באַווײַז פֿאַר אַן ווירקונג. פֿאַרבײַט נישט קיין דאָקטער.","detail":"קורס וועגן Reiki, אַ גײַסטיקע פּראַקטיק: איבערבליקן געפֿינען נישט גענוג באַווײַזן פֿאַר קיין ווירקונג אַחוץ אָפּרו/פּלאַסעבאָ; פֿאַרבייט נישט קיין דאָקטער.","tags":["קולטור"]},"Bioenergoterapie":{"line":"אַ קורס וואָס דערקלערט וואָס ביאָענערגעטישע טעראַפּיע איז און פֿון וואַנען זי קומט. עס איז נישטאָ קיין וויסנשאַפֿטלעכער באַווײַז פֿאַר אַ היילנדיקער ווירקונג; פֿאַרבײַט נישט קיין דאָקטער.","detail":"קורס וועגן ביאָענערגיע־טעראַפּיע, אַ פּראַקטיק אָן וויסנשאַפֿטלעכע באַווײַזן פֿון היילונג; פֿאַרבייט נישט קיין דאָקטער.","tags":["קולטור"]},"CHIROMANTIA":{"line":"אינטעראַקטיווער אַטלאַס פֿון כיראָמאַנטיע: מאַפּע פֿון דער האַנטפֿלאַך מיט ליניעס, בערגלעך, פֿינגער און האַנט־טיפּן, געלייענט ווי קולטורעלע טראַדיציע; מיט אַ טייל וועגן וויסנשאַפֿט און קריטישן טראַכטן. אָן וויסנשאַפֿטלעכער באַשטעטיקונג.","detail":"אינטעראַקטיווער אַטלאַס פֿון כּיראָמאַנטיע: אַ SVG־מאַפּע פֿון דער האַנט (לינקע/רעכטע), שורות, בערגלעך, פֿינגער, האַנט־טיפּן, פֿינגערפּרינטס, 2D:4D־מעסונגען, געפֿירטע לייענונג, קאַרטלעך, אַ קוויז, אַ Barnum־בלינדער טעסט און אַ cold-reading־סימולאַטאָר; יעדע טענה האָט אַ באַווײַז־מדרגה.","tags":["כיראָמאַנטיע","קולטור"]},"Radiestezie":{"line":"גייט דורך 18 לעוולען פֿון זוך מיט אַ רוט, מיט ווערטערבוך, פּראַקטיק־טאָגבוך און אינטערנאַציאָנאַלע אַפּליקאַציעס. זאָגט פֿון אָנהייב אַז עס האָט קיין וויסנשאַפֿטלעכע באַשטעטיקונג נישט.","detail":"אַ קורס אין 18 מדרגות וועגן וואַסערזוכעריי (dowsing), מיט אַ גלאָסאַר, פּראַקטיק־לאָגבוך און אינטערנאַציאָנאַלע אַפּענדיקסן; זאָגט פֿון אָנהייב אָן אַז עס האָט קיין וויסנשאַפֿטלעכע באַשטעטיקונג נישט.","tags":["קולטור"]},"Inforenergetica":{"line":"דערגייט אין אַ סטרוקטורירטן קורס וואָס אינפֿאָרענערגעטיק באַהויפּט, אַן אומטראַדיציאָנעלע פּראַקטיק. אָן וויסנשאַפֿטלעכער באַשטעטיקונג; נישט קיין מעדיציניש עצה.","detail":"קורס וועגן inforenergetics, אַן אומקאָנווענציאָנעלע פּראַקטיק אָן וויסנשאַפֿטלעכע באַשטעטיקונג; נישט קיין מעדיצינישער עצה.","tags":["קולטור"]},"ECLIPSA":{"line":"דערגייט אין וועלכן אַסטראָלאָגישן הויז פֿון אײַער געבורט־מאַפּע די פֿינצטערניש פֿאַלט, און וועגן די קומענדיקע 12 פֿינצטערנישן. די רעכענונג איז בערך, די אויסטײַטש סימבאָליש; אָן וויסנשאַפֿטלעכער באַשטעטיקונג.","detail":"אין וועלכן אַסטראָלאָגישן הויז פֿאַלט אַ פֿינצטערניש אויף אַ געבורט־קאַרטע, פּלוס די קומענדיקע 12 פֿינצטערנישן. לאָקאַלע, אָפּגעשאַצטע אַסטראָנאָמישע חשבונות; סימבאָלישע אויסטײַטש, אַסטראָלאָגיע האָט קיין וויסנשאַפֿטלעכע באַשטעטיקונג נישט.","tags":["אַסטראָלאָגיע"]},"Afrodisiace-fara-frontiere":{"line":"לייענט וועגן 22 עסנווארג און געוויקסן וואָס מען פֿאַרבינדט טראַדיציאָנעל מיט תּאווה, מיט דעם גראַד פֿון באַווײַז פֿאַר יעדן. קולטורעלער גיידבוך פֿאַר דערוואַקסענע, נישט קיין מעדיציניש עצה.","detail":"קולטורעלער פֿירער צו 22 עסנוואַרג און געוויקסן וואָס ווערן טראַדיציאָנעל פֿאַרבונדן מיט תּאווה, מיט אַ באַווײַז־מדרגה פֿאַר יעדן אײַנטראָג. דערציִונגס־, נישט קיין מעדיצינישער עצה.","tags":["קולטור"]},"CalmWaves":{"line":"אַמביענט־מוזיק פֿאַר ענטשפּאַנונג און שלאָף, וואָס שאַפֿט זיך אין גאַנג. נישט קיין מעדיציניש מכשיר; דער פֿאָרשונג־טייל איז נישט אומאָפּהענגיק קאָנטראָלירט. פֿרעגט אַן אַרצט (עפּילעפּסיע).","detail":"גענעראַטיווע אַמביענט־מוזיק פֿאַר אָפּרו/שלאָף. נישט קיין מעדיצינישער אַפּאַראַט; די פֿאָרשונג־אָפּטייל איז נישט אומאָפּהענגיק באַשטעטיקט. פֿרעגט אַ דאָקטער (עפּילעפּסיע).","tags":["אויַדיאָ"]},"ASMR":{"line":"בויט אײַער אײגענע באַרויקנדיקע קלאַנג־לאַנדשאַפֿט פֿון שיכטן פֿון סביבֿה, קלאַנגען פֿון באַרירונג און ביינאַוראַלע קלאַפּן. האָט אַ שלאָף־טײַמער, און איר קענט טיילן אײַער מישונג.","detail":"אָפּרו־קלאַנג־מישער גענערירט אין ריאַל־צײַט (Web Audio): אַמביענט־שיכטן, באַריר־קלאַנגען, בינאַוראַלע שלאָגן און אַ שלאָף־טײַמער; טײלבאַרע מישונג.","tags":["אויַדיאָ"]},"NOMIA":{"line":"ווי דער ערשטער קאָנטאַקט צווישן מענטשן, AI און אַנדערע סאָרטן אינטעליגענץ קען אויסזען. 1001 אויסגעטראַכטע סצענאַרן; בעלעטריסטיק, נישט ווירקלעכקייט. אַרבעט אויך אָפֿלײַן.","detail":"קאָנצעפּטועלער סימולאַטאָר פֿון קאָנטאַקט־פּראָטאָקאָלן מענטש–AI–NHI, 1001 אײַנטראָגן, באַגלייטער צו דער אַנטאָלאָגיע „Printre inteligențe“. פֿיקציע/ספּעקולאַציע, נישט באַשטעטיקטע פֿאַקטן; אָפֿליין PWA, RO/EN.","tags":["בעלעטריסטיק","השערה","PWA"]},"ValeaPlopului1972":{"line":"זעט דעם UFO־פֿאַל פֿון 1972 פֿון דרויסן, פֿון אינעווייניק און אין סימולאַציע, ריקאָנסטרויִרט אין 3D. דאָס איז אַן אויסגעטראַכטע הנחה, נישט קיין באַווײַז.","detail":"3D־רעקאָנסטרוקציע פֿון דעם UAP־פֿאַל פֿון Valea Plopului (1972): אַרויסן, סימולאַציע, פֿאַרגענצטער אינעווייניקסטער. ספּעקולאַטיוו, באַזירט אויף נישט־באַשטעטיקטע עפֿנטלעכע קוואַלן, אָן דער הסכּמה פֿון די געהייסענע מענטשן; נישט קיין באַווײַז.","tags":["UFO","3D","בעלעטריסטיק"]},"HoroScop":{"line":"רעכנט די שטעלעס פֿון פּלאַנעטן פֿאַר אַ דאַטום און אָרט, דערנאָך דערגייט די געבורט־מאַפּע, אַספּעקטן און צוגעפּאַסטקייט. סימבאָלישע אַסטראָלאָגיע, אָן וויסנשאַפֿטלעכער באַזע. אַרבעט אָפֿלײַן.","detail":"אָפֿליין פּערזענלעכע עפֿעמעריד: פּלאַנעטן־פּאָזיציעס אויסגערעכנט אין בראַוזער (פֿאַרקלענערטע גענויקייט), געבורט־קאַרטע, אַספּעקטן, סינאַסטריע. סימבאָלישע אַסטראָלאָגיע, קיין וויסנשאַפֿטלעכע באַשטעטיקונג; MIT־ליצענץ.","tags":["אַסטראָלאָגיע","עפֿעמעריד","אָפֿלײַן"]},"Aurora":{"line":"הערט באַרויקנדיקע טענער און לײַכטע קלאַפּנדיקע קלאַנגען און פֿאָלגט דעם אָטעם־גיידער. נאָר פֿאַר ענטשפּאַנונג, נישט קיין היילונג. אַרבעט אָן אינטערנעץ.","detail":"קלאַנג־הייליקטום: טשאַקרע־טענער, בינאַוראַלע שלאָגן און אַן אָטעם־פֿירער, אָפֿליין. נאָר אָפּרו, נישט קיין מעדיצין; די פֿרעקווענצן האָבן קיין וויסנשאַפֿטלעכע באַשטעטיקונג. MIT־ליצענץ; אומאָפּהענגיקער פּראָיעקט.","tags":["מעדיטאַציע","אויַדיאָ","ענטשפּאַנונג"]},"NumeroLogIA":{"line":"דערגייט וואָס נומעראָלאָגיע, כינעזישע BaZi־אַסטראָלאָגיע און ביאָריטם זאָגן וועגן אײַער געבורט־דאַטום, מיט אַ דערקלערונג פֿון יעדער רעכענונג. סימבאָלישע סיסטעם, אָן וויסנשאַפֿטלעכער באַזע.","detail":"פּיטאַגאָרעישע/כּאַלדעישע נומעראָלאָגיע, BaZi און ביאָריטם אין 7 שפּראַכן, חשבונות שריט־פֿאַר־שריט, פּאָרטרעטן עקספּאָרטירבאַר ווי JSON; אַפּציאָנעלער AI־אָראַקל דורך אײַער אייגענעם מאָדעל. סימבאָלישע סיסטעם, קיין וויסנשאַפֿטלעכע באַשטעטיקונג; MIT־ליצענץ.","tags":["נומעראָלאָגיע","AI","אָפֿלײַן"]},"FrequencyLaboratory":{"line":"פּרוּווט קלאַנגען, עפֿעקטן און געהער־טעסטן אין אַ קליינער קלאַנג־לאַבאָראַטאָריע. „טעראַפּעוטישע“ ווירקונגען זענען נישט באַוויזן; פֿאַרבײַט נישט קיין דאָקטער. אַרבעט אָפֿלײַן.","detail":"אַודיאָ־לאַבאָראַטאָריע אין בראַוזער (אָסצילאַטאָרן, בינאַוראַל, עפֿעקטן, אַנאַליזאַטאָרן, געהער־טעסטן), אָפֿליין. נאָר פֿאַר אינפֿאָרמאַציע: די „טעראַפּעוטישע“ פּרעסעטס האָבן קיין באַוויזענע מעדיצינישע ווירקונג; נישט קיין מעדיצינישער אַפּאַראַט.","tags":["אויַדיאָ","לאַבאָראַטאָריע","אָפֿלײַן"]},"generator-frecvente":{"line":"שאַפֿט ריינע טענער און פּאָרן מיט קלאַפּן, הערט באַקאַנטע פּרעסעטן און קאָנטראָלירט בערך אײַער געהער. נישט קיין מעדיציניש מכשיר. אַרבעט אָפֿלײַן.","detail":"טאָן־גענערייטאָר אין בראַוזער (בינאַוראַל, סעקווענצער, EQ, אָנווײַזנדיקער געהער־טעסט, זוך פֿון פּרעסעטס), אָפֿליין. נאָר פֿאַר אינפֿאָרמאַציע: די Solfeggio/Schumann־פּרעסעטס האָבן קיין וויסנשאַפֿטלעכע באַשטעטיקונג; נישט קיין מעדיצינישער אַפּאַראַט.","tags":["אויַדיאָ","גענערייטאָר","אָפֿלײַן"]},"ACORDAJ":{"line":"קוקט איבער טויזנט גײַסטיקע קורסן און איניציאַציעס מיט היסטאָרישן קאָנטעקסט און קריטישן בליק. נישט פֿאַרבונדן מיט דער קוואַל־זײַט און אָן וויסנשאַפֿטלעכער באַשטעטיקונג. אַרבעט אָפֿלײַן.","detail":"אָפֿליין אַטלאַס פֿון די 1134 גײַסטיקע קורסן/איניציאַציעס (די רשימה פֿון cursurispirituale.webnode.ro, נישט פֿאַרבונדן), מיט היסטאָרישן קאָנטעקסט און קריטישער אונטערשיידונג; קיין וויסנשאַפֿטלעכע באַשטעטיקונג.","tags":["גײַסטיקייט","אַטלאַס","קריטישע אונטערשיידונג"]},"Profund":{"line":"150 פֿראַגעס וואָס פֿירן דעם שמועס פֿאַרבײַ ליידיקן רעדן, צווישן פֿרײַנד אָדער אין דער משפּחה. שפּילט אויפֿן עקראַן אָדער דרוקט, מיט אַן אָפּציאָנעלן טײַמער.","detail":"אַ שפּיל פֿון 150 פֿראַגעס פֿאַר באַטײַטפֿולע שמועסן (RO/EN/FR), אָנליין אָדער געדרוקט, מיט שפּילער און אַן אַפּציאָנעלן טײַמער; אָנגעפּאַסט פֿון deepcards.org, די אָריגינעלן בלײַבן דער אײגנטום פֿון זייערע רעכט־האָבער (MIT נאָר פֿאַרן קאָד און דעם אָריגינעלן טייל).","tags":["שמועס","קאַרטן","trade-free"]},"Universul-Observabil":{"line":"ווי גרויס איז דער זעבאַרער אוניווערס? פֿאַרגלײַכט דרײַ מאַפּעס (לינעאַר, פֿלאַך, אין פּלאַץ) און מאַכט קאָסמאָלאָגישע רעכענונגען. די צאָלן זענען נישט אומאָפּהענגיק קאָנטראָלירט.","detail":"הויפּט־זײַט וואָס שטעלט פֿאָר און פֿאַרגלײַכט די 1D־, 2D־ און 3D־וויזואַליזאַציעס פֿון דעם אַבזערוואַבלען אוניווערס, מיט אַן אָפֿליין קאָסמאָלאָגישן רעכענער; צאָלן און רעקאָרדן זענען פֿון דעם קאַטאַלאָג פֿון מײַ 2026, נישט אומאָפּהענגיק באַשטעטיקט. RO/EN.","tags":["אַסטראָנאָמיע","קאָסמאָלאָגיע","וויזואַליזאַציע"]},"Universul-Observabil-1D":{"line":"פֿאָרט פֿון אונדז ביזן ראַנד פֿונעם זעבאַרן אוניווערס, פֿאַרבײַ 112 גאַלאַקסיעס אויף איין אַקס. אײראָנישער טאָן, אָפּגערונדעטע ווערטן, לערן־ציל.","detail":"1D־מאַפּע פֿון דעם אַבזערוואַבלען אוניווערס: 112 גאַלאַקסיעס אויף אַ ראַדיאַלער אַקס (צײַט, ווײַטקייט, רויטע פֿאַרשיבונג), מיט אַ דאַטן־טאַבעלע און CSV־עקספּאָרט. דערציִונגס־, מיט אַן איראָנישן טאָן; אָפּגערונדענע ווערטן, רעקאָרדן לויט דעם קאַטאַלאָג־דאַטום (מײַ 2026).","tags":["אַסטראָנאָמיע","קאָסמאָלאָגיע","וויזואַליזאַציע"]},"Universul-Observabil-2D":{"line":"מאַפּע פֿון גאַלאַקסיעס מיט סאַטירישער „פֿלאַכער ערד“־אויסגאַבע; אַ וויץ, די ערד איז נישט פֿלאַך. צוגעמען זיך צו 111 גאַלאַקסיעס; ווײַטקייטן זענען בערך. אַרבעט אָפֿלײַן.","detail":"אינטעראַקטיווע 2D־מאַפּע פֿון דעם אַבזערוואַבלען אוניווערס (111 גאַלאַקסיעס, לאָגאַריטמישע סקאַלע, JWST־דאַטן) אין אַ סאַטירישער „פֿלאַכער ערד“־אויסגאַבע: פּאַראָדיע, די ערד איז נישט פֿלאַך; ווײַטקייטן זענען אָפּגעשאַצט. RO/EN, אָפֿליין.","tags":["אַסטראָנאָמיע","סאַטירע","קאָסמאָלאָגיע"]},"Universul-Observabil-3D":{"line":"פֿליִט איבער 115 גאַלאַקסיעס אין אַ 3D־מאַפּע, מיט געפֿירטע רײַזעס און מישאַנען. די ווערטן זענען בערך.","detail":"אינטעראַקטיווע 3D־מאַפּע (WebGL) פֿון דעם אַבזערוואַבלען אוניווערס: 115+ גאַלאַקסיעס, 12 האָריזאָנטן, 30 טורן, אויפֿגאַבעס אין דעם פֿירער, GLB/CSV/BibTeX־עקספּאָרט. אָפּגעשאַצטע ווערטן; JWST־רעקאָרדן לויט מײַ 2026.","tags":["אַסטראָנאָמיע","קאָסמאָלאָגיע","3D"]},"QSO":{"line":"פֿירט דאָס טאָגבוך פֿון ראַדיאָ־פֿאַרבינדונגען פֿון אײַער ליבהאָבער־סטאַנציע, מיט UTC־צײַט, לאָקאַטאָרס און סטאַטיסטיק. נישט אָפֿיציעל; די רעכענונגען זענען בערך.","detail":"אומאָפֿיציעלער לאָגבוך פֿון אַ ליבהאָבער־ראַדיאָ־סטאַנציע: QSO־ס מיט אַן UTC־זייגער, ADIF 3.1־אימפּאָרט/עקספּאָרט, Maidenhead־לאָקאַטאָרן, קאָנטראָל פֿון דופּלירונגען, סטאַטיסטיק. טיילווײַזע פּרעפֿיקס־טאַבעלע (נישט DXCC); אָפּגעשאַצטע חשבונות.","tags":["ראַדיאָ","טאָגבוך"]},"Curatitor":{"line":"זעט וואָס אײַערע בילדער און טעקעס אַנטפּלעקן (אָרט, קאַמערע, מחבר) און באַזײַטיקט די דאַטן איידער איר שיקט. באַהאַלט נישט פּנימער אָדער אַנדערן זעבאַרן אינהאַלט.","detail":"ווײַזט און נעמט אַראָפּ מעטאַדאַטן פֿון טעקעס לאָקאַל (GPS, קאַמעראַ, מחבר, ווײַכוואַרג) אָן ווידער־קאָדירן פּיקסעלן אָדער קלאַנג, און קאָנטראָלירט ווידער דעם רעזולטאַט. ער מאַכט נישט אַנאָנים דעם אינהאַלט (פּנימער, סענסאָר־ראַש).","tags":["מעטאַדאַטן","פּריוואַטקייט"]},"Poteca":{"line":"עפֿנט שפּורן פֿון אַ וואַנדערונג אָדער ראָווער־פֿאָרן און זעט די ווײַטקייט, דעם אױפֿשטײַג און דעם הייך־פּראָפֿיל. איר קענט שנײַדן אָדער פֿאַראײניקן. אָן מאַפּע; דער אױפֿשטײַג איז געשאַצט.","detail":"בלאָטער און רעדאַקטאָר פֿאַר GPX/GeoJSON/KML/CSV־שפּורן: סטאַטיסטיק, הייך־פּראָפֿיל, שנײַדן, פֿאַראײניקן, פּשוטן, עקספּאָרט. קיין באַזע־מאַפּע; אַרויפֿגאַנג/אַראָפּגאַנג זענען אָפּשאַצונגען.","tags":["GPX","שפּורן"]},"Orar":{"line":"קאַלענדאַר און וואָכן־פּלאַנער מיט אָפֿיציעלע ראָמענישע יום־טובֿים, מיט אַ טאָג־, וואָך־ אָדער חודש־אַנזיכט. וועקערס קלינגען נאָר אַזוי לאַנג די זײַט איז אָפֿן.","detail":"קאַלענדאַר און וואָכן־פּלאַנער: חודש־/וואָך־/טאָג־/אַגענדע־אָנזיכטן, RFC 5545־ווידערהאָלונגען, צײַט־זאָנעס, רומענישע שטאַטלעכע יום־טובֿים, .ics־אימפּאָרט/עקספּאָרט. וועקערס קלינגען נאָר בעת דער טאַב איז אָפֿן.","tags":["קאַלענדאַר","צײַט"]},"Alfabete":{"line":"לערנט און טרענירט מאָרזע, בריִיל, פֿאָנעטישן אַלפֿאַבעט, פֿאָן־סעמאַפֿאָר און אַלטע שיפֿרן, דערנאָך דרוקט די זײַט. אַלטע שיפֿרן באַשיצן נישט קיין סודות.","detail":"רעפֿערענץ, קאָנווערטער, טרענער און דרוקבאַר בלאַט פֿאַר מאָרזע, בראַיל (גראַד 1), פֿאָנעטישע אַלפֿאַבעטן, סעמאַפֿאָר, Baudot, צאָל־סיסטעמען און קלאַסישע שיפֿרן. קלאַסישע שיפֿרן בייטן קיין זיכערקייט נישט.","tags":["קאָדן","לערנען"]},"Fabrica":{"line":"שרײַבט אַ קורס ווי פּשוטער טעקסט און פֿאַרוואַנדלט אין אַ זײַט מיט לעקציעס, סוף־טעסט און דרוקבאַר צערטיפֿיקאַט. דער צערטיפֿיקאַט האָט קיין אָפֿיציעלן ווערט נישט.","detail":"פֿאַבריק פֿון קורסן און קוויזן: שרײַבט אַ קורס אין פּשוטן Markdown און עקספּאָרטירט אים ווי איין זעלבסטשטענדיקע HTML־טעקע מיט לאָקאַלער פּראָגרעס, אַ לעצטן טעסט און אַ דרוקבאַרן סערטיפֿיקאַט (קיין אַקרעדיטירונג־ווערט).","tags":["קורסן","שאַפֿן"]},"Bolta":{"line":"ווי האָט דער הימל אויסגעזען איבערן קאָפּ אין יעדן אָרט און צײַט צווישן 1900 און 2100? די זון, דער לבֿנה, פּלאַנעטן און שטערן, און די פֿינצטערניש פֿון 2027. ווערטן זענען גערעכנט, נישט אָפֿיציעל. אַרבעט אָפֿלײַן.","detail":"אָפֿליין פּלאַנעטאַריום פֿאַר יעדן אָרט און צײַט צווישן 1900 און 2100: זון, לבֿנה, פּלאַנעטן, 1,627 שטערן, שטערנבילדער, געשעענישן און אַ זײַט וועגן דער פֿינצטערניש פֿון 2027. אויסגערעכנטע ווערטן, נישט אָפֿיציעל.","tags":["אַסטראָנאָמיע","פּלאַנעטאַריום"]},"BRAZDA":{"line":"דעשיפֿרירט די גאָלדענע פּלאַטע פֿון וויאָדזשער שריט פֿאַר שריט, דערנאָך קאָדירט אַ נײַע פּלאַטע פֿאַר אַ זאָנד וואָס ווערט איצט אָפּגעשיקט. די בילדער פֿון די ערשטע שריט זענען סכעמאַטיש, נישט פֿון NASA.","detail":"אַ 12־שריט דעקאָדער און ענקאָדער פֿאַר דער Voyager Golden Record: גיכקייט, די הידראָגען־זייגער, די פּולסאַר־מאַפּע, דער סיגנאַל פֿון אַ בילד, קאַליבראַציע מיטן קרײַז, שורה־פֿאַר־שורה דעקאָדירונג, קאָליר, אײַער אייגענע טעקע, בײַטראָגן און די ענקאָדירונג פֿון אַ דיסק 2026–2027.","tags":["וויאָדזשער","סיגנאַל"]},"Arbore":{"line":"בויט אַ משפּחה־בוים מיט מענטשן, משפּחות, צײַט־ליניע און אַ ראָמענישן רעכענער פֿון קרובֿישאַפֿט. די דאַטן בלײַבן נאָר אין דעם בראַוזער, אָן סינכראָניזירן.","detail":"לאָקאַלע גענעאַלאָגיע: מענטשן, משפּחות, GEDCOM 5.5.1־אימפּאָרט/עקספּאָרט, SVG־דיאַגראַמען, צײַט־שורה, קרובֿישאַפֿט־רעכענער (נאָר רומענישע טערמינאָלאָגיע). קיין סינכראָניזאַציע; דאַטן בלײַבן אין דעם בראַוזער.","tags":["גענעאַלאָגיע","GEDCOM"]},"Gospodar":{"line":"פֿאָלגט נאָך די היימישע געלט: קאָנטעס, הוצאָות, חודשלעכע בודזשעטן און באַריכטן. אָן קאָנטאָ, אָבער פֿאַרלירט איר דאָס פּאַראָל, פֿאַרלירט איר די דאַטן. נישט קיין פֿינאַנציעלע עצה.","detail":"לאָקאַלער הויז־בודזשעט: קאָנטעס, קאַטעגאָריעס, טראַנסאַקציעס, CSV־אימפּאָרט, מאָנאַטלעכע בודזשעטן, באַריכטן און רעכענער מיט דורכזיכטיקע פֿאָרמולן. קיין קאָנטאָ אָדער סינכראָניזאַציע; אַ פֿאַרלוירענער פּאַסוואָרט מיינט פֿאַרלוירענע דאַטן. נישט קיין פֿינאַנציעלער עצה.","tags":["בודזשעט","פּערזענלעכע פֿינאַנצן"]},"Decibel":{"line":"מעסט ווי הויך דער ראַש אַרום אײַך איז און זעט פֿון וואָס פֿאַר קלאַנגען ער באַשטייט. עס איז אויך דאָ אַ בערך געהער־טעסט. נישט קיין צערטיפֿיצירט מכשיר; די רעזולטאַטן הענגען פֿון דעם מיקראָפֿאָן.","detail":"קלאַנג־מדריגה־מעסטער, ספּעקטער־אַנאַליזאַטאָר (1/3 אָקטאַוו, FFT) און אַן אָנווײַזנדיקער געהער־טעסט. נישט קיין סערטיפֿיצירטער מעסטער און אָן יורידישן אָדער מעדיצינישן ווערט; מעסונגען הענגען אָפּ פֿון דעם מיקראָפֿאָן און דער קאַליבראַציע.","tags":["קלאַנג","מעסונג"]},"Provenienta":{"line":"האָט איר אַ בילד און ווילט וויסן ווער האָט עס אונטערגעשריבן און וועלכע רעדאַקציעס זענען דערקלערט? קאָנטראָלירט די אײַנגעבויטע דיגיטאַלע אונטערשריפֿט. עקספּערימענטעל, נאָר מיט בײַשפּיל־טעקעס געטעסט.","detail":"לאָקאַלער, עקספּערימענטאַלער C2PA / Content Credentials־קאָנטראָלער: ווײַזט ווער האָט אונטערגעשריבן און וועלכע ענדערונגען זענען דעקלאַרירט, און באַשטעטיקט די אונטערשריפֿט און די בינדונג צו די בײַטן פֿון דער טעקע. געטעסט נאָר אויף סינטעטישע טעקעס; קיין פֿאַרטרוי־רשימה.","tags":["C2PA","אָפּשטאַם"]},"Lexicon":{"line":"ברענגט אײַערע אײגענע ווערטערביכער און זוכט ווערטער, אַפֿילו ווען איר שרײַבט אָן דיאַקריטישע צייכנס אָדער מיט טעותים. קומט נאָר מיט אַ קליינער דעמאָ־זאַמלונג. אַרבעט אָפֿלײַן.","detail":"אָפֿליין ווערטערבוך־מאָטאָר: ברענגט אײַערע אייגענע ווערטערביכער (TSV/CSV, JSON, StarDict, dictd, XDXF) און זוכט לויט פּרעפֿיקס, אָן אַקצענט, פֿאַזי אָדער פֿולטעקסט. די מיטגעלייגטע זאַמלונג (345 אײַנטראָגן) איז אַ דעמאָ, נישט קיין פֿולשטענדיק ווערטערבוך.","tags":["ווערטערבוך","שפּראַך"]},"VERIGA":{"line":"געפֿינט צעבראָכענע לינקס און יתומים־טעקעס אין אַ זײַט אָדער טעקע. אַרבעט אויף Windows, macOS און Linux; פֿאָדערט אַ ביסל קאָמפּיוטער־וויסן.","detail":"לינק־קאָנטראָלער (clean-room) פֿאַר וועבזײַטן און לאָקאַלע טעקע־פּאַפּקעס, געשריבן אין Rust: באַפֿעל־שורה, נאַטיווע דעסקטאַפּ־אַפּ (egui) און אַן איינציקע־טעקע HTML־ווערסיע. קאָנטראָלירט HTML־ און CSS־לינקס, ווײַטערפֿירונגען, #fragment־אַנקערס, יתומים־טעקעס, robots.txt און sitemap. Windows, macOS און Linux; MIT־ליצענץ.","tags":["לינק־קאָנטראָל","MIT"]},"TEZAUR":{"line":"דיסערטאַציע־העלפֿער וואָס שרײַבט נאָר פֿון אײַערע אײגענע ביכער און אַרטיקלען, מיט איבערצופּרוּווענדיקע ציטאַטן. אַרבעט אויף אײַער קאָמפּיוטער; אײַערע דאָקומענטן פֿאַרלאָזן אים קיינמאָל נישט. אין אַנטוויקלונג.","detail":"לאָקאַלער פֿאָרשונג־אַסיסטענט פֿאַרן שרײַבן אַ טעזיס, געשריבן אין Rust, מיט ענטפֿערס באַזירט אויף ציטאַטן: ער אינדעקסירט אײַערע ביכער און אַרטיקלען (PDF, EPUB, DOCX, txt), געפֿינט פּאַסאַזשן און שרײַבט נאָר פֿון זיי, מיט קאָנטראָלירטע [n]־ציטאַטן און אַ ביבליאָגראַפֿיע. לויפֿט אויף אײַער אייגענעם קאָמפּיוטער מיט אַ לאָקאַלן מאָדעל (Ollama, Jan, LM Studio); אײַערע דאָקומענטן פֿאַרלאָזן אים קיינמאָל נישט. ווערסיע 0.x; MIT־ליצענץ.","tags":["פֿאָרשונג","MIT"]},"LegatorOCR":{"line":"סקאַנירט אַ בוך און קריגט אַ ריינעם PDF מיט אויסגעגלײַכטע זײַטלעך און זוכבאַרן טעקסט. אַרבעט אויף Windows, macOS און Linux; אײַערע סקאַנס בלײַבן בײַ אײַך.","detail":"Clean-room נאָכפּראָצעסאָר געשריבן אין Rust פֿאַר געסקאַנירטע ביכער: טיילט צווײַ־זײַטיקע שפּרײַטונגען, פֿאַרריכט שיעפּקייט, שנײַדט, שטעלט ראַנדן, רײניקט און באַנאַריזירט, דערנאָך עקספּאָרטירט אַ PDF אָדער בילדער מיט אַן דורכזוכבאַרער OCR־טעקסט־שיכט. גראַפֿישע אַפּ (Windows, macOS, Linux) און באַפֿעל־שורה, אין 8 שפּראַכן. טעקסט־דערקענונג (OCR) דאַרף דאָס באַזונדערע פּראָגראַם Tesseract; אַלץ אַנדערש אַרבעט אָן אים. ווערסיע 0.x; MIT־ליצענץ.","tags":["סקאַנירן","MIT"]},"Fenarium":{"line":"אַטלאַס און וואַרשטאַט פֿון סובֿיעקטיווע באַמערקונגען מיט אַלע זינען, אָנהייבנדיק מיט פֿאָספֿעניזם: קורס פֿון 13 מאָדולן, געפֿירטע עקספּערימענטן, וויזועלער סימולאַטאָר און לאַבאָראַטאָריע פֿאַר A/B זעלבסט־עקספּערימענטן מיט ראַנדאָמיזירונג. אויסבילדונג, נישט קיין מעדיציניש מכשיר.","detail":"אַטלאַס פֿון פֿענעס (פֿאָספֿענען, נאָכבילדער, טינעטוס־ענלעכע קלאַנגען און מער), אַ 13־מאָדול־קורס, אַ לאַבאָראַטאָריע פֿאַר זעלבסט־עקספּערימענטן; נישט קיין מעדיצינישער אַפּאַראַט.","tags":["באַמערקונג","MIT"]},"MENSURA":{"line":"מעסט IQ, EQ, CQ, RQ, עקזעקוטיווע פֿונקציעס און זינען אין 6 געביטן מיט 18 טעסטן, קאָמפּאָזיט־אינדעקסן און 95%־פֿאַרטרויען־אינטערוואַלן. צײַטווײַליקע נאָרמעס, נאָר בערך, נישט קיין דיאַגנאָז.","detail":"18 טעסטן אין 6 געביטן (IQ, EQ, CQ, RQ, עקזעקוטיווע פֿונקציעס, סענסעס), אינדעקסן מיט קאָנפֿידענץ־אינטערוואַלן, JSON־עקספּאָרט/אימפּאָרט; פּראָוויזאָרישע נאָרמעס.","tags":["טעסטן","MIT"]},"Cronosala":{"line":"טײַמערס פֿאַר אַ ספּאָרט־זאַל: רו צווישן סעריעס, HIIT, Tabata, EMOM, AMRAP, קרײַזן און מעטראָנאָם, און אַ טרענירונג־טאָגבוך מיט קג און איבערחזרונגען.","detail":"פֿיטנעס־טײַמערס און אַ טרענירונג־לאָגבוך אין איין HTML־טעקע: אַדאַפּטיווע רו צווישן סעטן, Interval/HIIT, Tabata, EMOM, AMRAP, סטאַנציע־קרײַזן, טעמפּאָ, מעטראָנאָם, אַ 4־וואָכיקע חודש־פּראָגראַם, אַ קאַטאַלאָג פֿון געניטונגען און QR־קאָדן פֿאַר מאַשינען. דאַטן בלײַבן אין בראַוזער; דער אינטערפֿייס איז אויף רומעניש.","tags":["ספּאָרט","צײַט"]},"ScutSonor":{"line":"הויכער קלאַנג און לאַמטערן־סטראָבאָסקאָפּ פֿאַר באַגעגענישן מיט אַגרעסיווע הינט, און אַ גיידבוך צום פֿאַרהאַלטן זיך. אַ הילף, נישט קיין געגאַראַנטירטער שילד.","detail":"גענערירט אַ 2–8 kHz־סוויפּ, עקספּערימענטאַלן אולטראַקלאַנג, אַ סירענע און אַ לאָדשפּרעכער־טעסט, מיט אַ לימיטער וואָס היט די לוטקייט, פֿלאַשליכט־סטראָבאָסקאָפּ (2.5 Hz), טאָגליכט־אופֿן און אַ זיכערקייט־פֿירער. איין טעקע, קיין נאָכפֿאָלגן. באַווײַזן אַז קלאַנג שרעקט אָפּ הינט זענען שוואַך.","tags":["זיכערקייט","קלאַנג"]},"MIRAJ":{"line":"ווי דער נעץ־הויט זעט און ווי דער מוח בויט דאָס בילד: צענטראַלע גרוב, בלינדער פּונקט, אילוזיעס און וויקטאָרינע, אויף דרײַ לעוולען.","detail":"אינטעראַקטיווע דערקלערונג פֿון זעאונג אויף דרײַ מדרגות (אָנהייבער, מיטל, פֿאָרגעשריטן): רעטינע, פֿאָווע, בלינדער פֿלעק, אָפּטישע אילוזיעס, אַ סך־הכּל און אַ 10־פֿראַגע־קוויז. איין טעקע, אינטערפֿייס אויף רומעניש און ענגליש.","tags":["זעונג","בילדונג"]},"ANTROPOS":{"line":"אַ בערך וויסנשאַפֿטלעכער פּראָפֿיל, גערעכנט אָרטיקלעך: PhenoAge ביאָלאָגישער עלטער, קול, האַנטשריפֿט, זייגער־ציינונג, TIPI פּערזענלעכקייט און ריאַקציע־צײַט.","detail":"אַ דערציִונגס־סקרינינג־געצײַג, נישט קיין דיאַגנאָז: PhenoAge ביאָלאָגישער עלטער מיט אַ פּלויזיביליטעט־שוץ, שטימע־אַנאַליז, האַנטשריפֿט־גראַפֿאָמעטריע, זייגער־ און צייכן־אַ־מענטש־טעסטן, TIPI, ריאַקציע־טעסטן, אַ דרוקבאַרער באַריכט און JSON־עקספּאָרט. דאַטן בלײַבן אין בראַוזער.","tags":["סקרינינג","ביאָלאָגיע"]},"DESCANTAR":{"line":"וואָרזאָגעריי מיט 41 באָבעס (3×3 מעטאָדע, אָלטעניש וואַריאַנט) און 12 טראַדיציאָנעלע בשׁבֿועות ווי אַ אָביעקט פֿון פֿאָלקלאָר־שטודיע.","detail":"רומענישע באָבן־וואָרזאָגעריי אין דרײַ מעטאָדן (3×3 לויט דעם בוך, Oltenia, דרײַ קופּעס), לייענונגען לויט קאָפּ, האַרץ און פֿוסן, 12 טראַדיציאָנעלע שפּרוכן, לבֿנה־פֿאַזע, דעקלאַמירונג־ציילער, שפּרוך־גענערייטאָר, געשיכטע און אַ קאָפּירבאַרער פֿירער. פֿאָלקלאָר־אינהאַלט איבערגעזעצט אין 8 שפּראַכן מיט AI, נישט איבערגעקוקט דורך געבוירענע רעדער.","tags":["פֿאָלקלאָר","באָבעס"]},"Index-fara-frontiere":{"line":"קאַטאַלאָג פֿון איין־טעקע HTML אַפּליקאַציעס: די chiuta.github.io־זאַמלונג און דרויסנדיקע קוואַלן, מיט זוך און טאַגס.","detail":"אַכט פּראָיעקטן פֿון דער זאַמלונג פֿון דעם מחבר און אַכט דרויסנדיקע רעסורסן, קלאָר מאַרקירט, מיט לעבעדיקער זוך, אָנקליקבאַרע טאַגס, אַן RO/EN־שאַלטער, טונקל/העל־טעמע און אַן אײַנטראָג וואָס קאַטאַלאָגירט זיך אַליין. קיין נעץ־בקשות. אַ סטאַטישער אָפּדרוק פֿון 5 יולי 2026.","tags":["קאַטאַלאָג","קוואַלן"]},"DECUPAJ":{"line":"פֿאַרוואַנדלט אַ פּאָדקאַסט, אויַדיאָ אָדער ווידעאָ אין ווערטיקאַלע קליפּן מיט אונטערטיטלען, גלײַך אין בראַוזער, אָן קאָנטאָ און וואַסערצייכן. אײַערע טעקעס פֿאַרלאָזן קיינמאָל נישט דעם מכשיר.","detail":"ווערטיקאַלע רילס פֿון אַ פּאָדקאַסט (אַודיאָ אָדער וידעאָ) אין איין HTML־טעקע: קלײַבט דעם אָפּשניט אויף דער כוואַליע־פֿאָרעם, באַקומט פֿאָרשלאָגן פֿון מאָמענטן, לאָקאַלע טראַנסקריפּציע מיט Whisper, סטיליזירטע אונטערשריפֿטן, 4 פֿאָרמאַט־פּראָפּאָרציעס (9:16, 4:5, 1:1, 16:9), אַן עקספּאָרט־ריי און MP4 דורך WebCodecs. אינטערפֿייס אין 8 שפּראַכן.","tags":["reels","ווידעאָ"]},"LECTOR":{"line":"ביכער הויך געלייענט גלײַך אין בראַוזער: EPUB, DOCX, PDF, TXT אָדער אײַנגעשטעלטער טעקסט, אָן קאָנטאָ און סערווער. דער טעקסט פֿאַרלאָזט קיינמאָל נישט אײַער מכשיר.","detail":"הערט ביכער פֿאָרגעלייענט פֿון איין HTML־טעקע: EPUB, DOCX, PDF (מיט רומענישן OCR פֿאַר סקאַנען), TXT; קולות פֿון דעם מכשיר אָדער Piper ro_RO, דאָס גערעדטע וואָרט אָנגעצייכנט, שלאָף־טײַמער, קאַפּיטלען, לעזעצייכנס, אַן אויסשפּראַך־ווערטערבוך, אַ לאָקאַלע ביבליאָטעק און דיסלעקסיע־פֿרײַנדלעכע טעמעס. אינטערפֿייס אין 8 שפּראַכן.","tags":["אויַדיאָ","ביכער"]},"FARFURIA":{"line":"פֿרײַער דיגיטאַלער דיעטאָלאָג: פּערזענלעכע קאַלאָריעס און מאַקראָס, 7־טעגיקער עסן־פּלאַן, עסן־טאָגבוך און וואָג־נאָכפֿאָלגונג. פֿאַרבײַט נישט קיין דאָקטער אָדער דיעטאָלאָג.","detail":"אַ דיגיטאַלער דיעטאָלאָג אין איין HTML־טעקע: ציל־ווערטן פֿאַר קאַלאָריעס און מאַקראָס (Mifflin–St Jeor, אַקטיוויטעט־מדרגה, ציל), אַ 7־טאָגיקער עסן־פּלאַן מיט פֿילטערס פֿאַר דיעטע און אַלערגענען, אַ דאַטנבאַזע פֿון עסנוואַרג, אַ עסן־טאָגבוך און געוויכט־נאָכפֿאָלגן. זיכערקייט־כּללים פֿאַר קינדער, געשיכטע פֿון עסן־שטערונגען און ניר־קראַנקייט. אינטערפֿייס אין 8 שפּראַכן.","tags":["עסן","געזונט"]},"VITALIS":{"line":"פּערזענלעכער באַגלייטער פֿאַר געזונט, לאַנגלעביקייט און ביאָהאַקינג: נײַן זײַלן געאָרדנט לויט באַווײַזן, רעכענער, לעבנס־שטייגער־אָפּשאַצונג און טעגלעכער ריטואַל. נישט קיין מעדיציניש עצה.","detail":"אַ געזונט־ און לאַנגלעבעדיקייט־באַגלייטער אין איין HTML־טעקע: ניין זײַלן געראַנגט לויט באַווײַזן, רעכענער (HOMA-IR, TyG, טאַליע־צו־הייך, Mifflin–St Jeor, האַרץ־שלאָג־זאָנעס, שלאָף־ציקלען, פּראָטעין), אַ פֿאַסטן־טײַמער, אַן אָטעם־שריטמאַכער, אַ 360־אָפּשאַצונג מיט ראַדאַר־דיאַגראַם, רעפֿערענץ־געביטן פֿון ביאָמאַרקערס און אַ טעגלעכער ריטואַל־נאָכפֿאָלגער. אומאָפֿיציעלער באַגלייטער פֿאַרן BioHacking360־געשעעניש. אינטערפֿייס אין 8 שפּראַכן.","tags":["געזונט","לאַנגלעביקייט"]},"REZONANTA":{"line":"גיידבוך און געצייגן פֿאַר קאָמוניקאַציע און מעדיע: אָנזאָג, קאַנאַלן, פּרעסע־מעלדונג, אינטערוויו, קלאָרקייט, פּלאַן און קריזיס.","detail":"ווי אַזוי מען מאַכט אַז מענטשן הערן זיך צו, אין איין HTML־טעקע: 12 פּרינציפּן מיט אַ פּראַקטישן טעסט, דאָס „באָטשאַפֿט־הויז“ (אַ 30־סעקונדן־פּיטש, אַ פּאָסט, אַ קורצע און אַ גערעדטע ווערסיע), רעקאָמענדאַציעס פֿאַר מעדיע־קאַנאַלן, אַ גענערייטאָר פֿון פּרעס־מעלדונגען מיט אַ פֿאַרקערטער פּיראַמידע, אַ אינטערוויו־בלאַט, אַן אַנאַליזאַטאָר פֿון טעקסט־קלאָרקייט, אַ קאָמוניקאַציע־פּלאַן מיט טעקסט/CSV־עקספּאָרט און די ערשטע־שעה־שריט פֿון אַ קריזיס. אינטערפֿייס אין 8 שפּראַכן.","tags":["קאָמוניקאַציע","מעדיע"]},"Claritas":{"line":"אומפֿאַרמאָגנדיקע בראַוזער־פֿאַרברייטערונג פֿאַר צוגענגלעכקייט: קאָנטראַסט־פֿאַרריכטונג, לייען־רעזשים, הויך־לייענען און WCAG־קאָנטראָל. אָן טעלעמעטריע, אָן נעץ, אָן קאָנטאָ.","detail":"אַ פֿרײַע צוטריט־ערווײַטערונג פֿאַרן בראַוזער: אויטאָמאַטישע קאָנטראַסט־פֿאַרריכטונג (WCAG AA/AAA), הויך־קאָנטראַסט־טעמעס, פֿילטערס פֿאַר קאָליר־בלינדקייט, גרעסערער טעקסט און דיסלעקסיע־פֿרײַנדלעכע שריפֿטן, לייען־לינעאַל, מאַסקע און פֿאַרגרעסער־גלאָז, לייענער־אופֿן, פֿאָרלייענען, גרויסע קליק־ציילן און איין־שאַלטער־סקאַנירונג, אַ WCAG 2.2־אויעדיט, לאָקאַלע סקרינשאָטן און עקראַן־אויפֿנאַמען. פֿאַר Chromium, Firefox און Safari; אינטערפֿייס אין 8 שפּראַכן.","tags":["צוגענגלעכקייט","פֿאַרברייטערונג"]},"TurboCursa":{"line":"פּסעוודאָ־3D אַרקייד־ראַס־שפּיל געשריבן אין Rust: לאַנדשאַפֿטן פֿון אַ זאַמען, 11 רעזשימען, ליגע־קאַריערע און 2 שפּילער. אָריגינעל; אָן קאָד אָדער רעסורסן פֿון אַנדערע שפּילן.","detail":"אַ clean-room פּסעוודאָ־3D אַרקייד־רעניש געשריבן אין Rust: אָריגינעלער מאָטאָר, קונסט, מוזיק און נאָמען, אַלץ גענערירט פֿון אַ זוימען (19 לאַנדשאַפֿטן), קאַמפּאַניע, צײַט־פֿאָרמאַט, אומענדלעך, Rush Hour, סלאַלאָם, שפּיגל, Blackout, Zen, קעגן CPU, צוויי־שפּילער געשפּאָלטענער עקראַן און אַ דיוויזיעס־קאַריערע. לויפֿט נאַטיוו אָדער ווי אַ וועב־טעקע; אינטערפֿייס אין 8 שפּראַכן.","tags":["ראַסן","Rust"]},"ANTENA":{"line":"אין אַנטוויקלונג: דראָט־אַנטענע־לייזער קאָמפּאַטיבל מיט NEC-2 (מאָמענטן־מעטאָדע) מיט בראַוזער־אינטערפֿייס. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ NEC-2־קאָמפּאַטיבלער דראָט־אַנטענע־סאָלווער (מאָמענטן־מעטאָד) מיט אַ בראַוזער־פֿראָנט־ענד. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["ראַדיאָ","אַנטענעס"]},"ARBITRU":{"line":"אין אַנטוויקלונג: אוניווערסאַלער כּללים־מאָטאָר פֿאַר טיש־, קאַרטן־, קוביה־ און רעטעניש־שפּילן מיט אַ דעקלאַראַטיווער שפּראַך פֿאַר כּללים. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ אוניווערסאַלער כּללים־מאָטאָר פֿאַר ברעט־, קאַרטן־, קוביה־ און רעטעניש־שפּילן, מיט אַ דעקלאַראַטיווער כּללים־שפּראַך. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["שפּילן","כּללים"]},"ASTROLABIU":{"line":"אין אַנטוויקלונג: מאָטאָר פֿאַר הימלישע געשעענישן אין ריינעם Rust (צײַט־סקאַלעס, פֿינצטערנישן, אויפֿגאַנגען און אונטערגאַנגען, קאַלענדאַרן). ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ מאָטאָר פֿאַר הימל־געשעענישן (צײַט־סקאַלעס, פֿינצטערנישן, אויפֿגאַנג און אונטערגאַנג, קאַלענדאַרן), אין פּורער Rust. ביז אַצונד נאָר אַ פּרע־אַלפֿא־סקעלעט.","tags":["אַסטראָנאָמיע","קאַלענדאַרן"]},"ECOGRAMA":{"line":"אין אַנטוויקלונג: רעדאַקטאָר פֿון ספּעקטראָגראַמען און קלאַנג־רעסטאַוואַציע: קלײַבט אויפֿן ספּעקטראָגראַם, פֿאַרריכט, עקספּאָרטירט. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ ספּעקטראָגראַם־רעדאַקטאָר און אַודיאָ־רעסטאָראַציע: סעלעקטירט אויפֿן ספּעקטראָגראַם, פֿאַרריכט, עקספּאָרטירט. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["אויַדיאָ","רעסטאַוואַציע"]},"ecou-spectral-rs":{"line":"אין אַנטוויקלונג: אָריגינעלער ספּעקטראָגראַם־רעדאַקטאָר אין Rust מיט פּלאַגינס פֿאַר רעש־רעדוצירונג און דעטעקציע פֿון קולות. עס זענען דאָ אַ קאָד־סקעלעט און אַ פּלאַגין־פֿאָרמאַט, אָבער נאָך נישט קיין גרייטע פֿונקציעס.","detail":"אין אַרבעט: אַ נאַטיווער Rust ספּעקטראָגראַם־רעדאַקטאָר מיט פּלאַגינס פֿאַר ראַש־רעדוקציע און שטימע־דעטעקציע. ער האָט אַ קאָד־סקעלעט און אַ פּלאַגין־פֿאָרמאַט, אָבער נאָך קיין פֿאַרטיקע פֿונקציע.","tags":["אויַדיאָ","Rust"]},"MARTOR":{"line":"אין אַנטוויקלונג: פֿאָרענזישע אָפּנעמען פֿון וועב מיט WARC/WACZ, מיט האַשעס, אונטערשריפֿטן און פֿאַרטרויטע צײַט־שטעמפּלען, אָפֿלײַן קאָנטראָלירבאַר. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: פֿאָרענזישע וועב־קאַפּטשור אין WARC/WACZ מיט האַשעס, אונטערשריפֿטן און פֿאַרטרויטע צײַט־שטעמפּלען, אָפֿליין פֿאַרבאַשטעטיקבאַר. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["אַרכיוויזירן","באַווײַזן"]},"NEAMURI":{"line":"אין אַנטוויקלונג: קרובֿישאַפֿט־מאָטאָר: פֿון אַ משפּחה־בוים־וועג צום ריכטיקן קרובֿישאַפֿט־טערמין אין פֿיל שפּראַכן. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ מאָטאָר פֿאַר קרובֿישאַפֿט, פֿון אַ משפּחה־בוים־וועג צום ריכטיקן קרובֿישאַפֿט־טערמין אין פֿיל שפּראַכן. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["קרובֿישאַפֿט","גענעאַלאָגיע"]},"TACTIL":{"line":"אין אַנטוויקלונג: שיכט פֿאַר טאַקטילער אויסגאַבע: בריִיל־פֿאָרמאַטן (BRF, Unicode), עקראַנען, רעליעף־דרוקערס און טאַטש־עקראַן־וויבראַציע. ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ טאַקטילע אויסגאַנג־שיכט: בראַיל־פֿאָרמאַטן (BRF, Unicode), דיספּלייס, אײַנדרוק־מאַשינען און טאַטש־עקראַן־וויבראַציע. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["בריִיל","צוגענגלעכקייט"]},"atelier-verificare":{"line":"קאָנטראָלירט בילדער, ווידעאָס, לינקס און דאָמענען אין אײַער בראַוזער, גאָרנישט ווערט אַרויפֿגעלאָדן: אמתער טעקע־טיפּ און SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (נאָר־לייענען), טעות־ניוואָ־אַנאַליז. קען נישט באַווײַזן אַז אַ בילד איז עכט. אַלפֿאַ.","detail":"אַ פֿאַרבאַשטעטיקונג־געצײַג־קעסטל פֿאַר זשורנאַליסטן און אָפּגעהיטענע לייענער וואָס לויפֿט לאָקאַל. לייגט צו בילדער, וידעאָס, לינקס, דאָמענען אָדער טעקסט און באַקומט פֿינדונגען מיט אַ מדרגה פֿון דאגה פֿאַר יעדן: דער אמתער טעקע־טיפּ, SHA-256, EXIF און GPS־פּאָזיציע, XMP און IPTC, שפּורן פֿון AI־בילד־גענערייטאָרן, Content Credentials־מאַניפֿעסטן (C2PA; געלייענט, נישט באַשטעטיקט), טעות־מדרגה־אַנאַליז פֿאַר JPEG, וידעאָ־מעטאַדאַטן מיט שליסל־פֿריימס פֿאַר פֿאַרקערטער בילד־זוך, און לינק־אַנאַטאָמיע. צוויי אַפּציאָנעלע נעץ־קאָנטראָלן (DNS־סך־הכּל, Internet Archive) לויפֿן נאָר נאָכן אָפּצייכענען אַ הסכּמה־קעסטל. דער באַריכט (Markdown, JSON אָדער PDF) ליסטעט די באַגרענעצונגען פֿון דער מעטאָדע. ער קען נישט באַווײַזן אַז אַ פֿאָטאָ איז אמת: פֿעלנדיקע מעטאַדאַטן זאָגן ווינציק און מעטאַדאַטן קען מען פֿאַלשן. אַלפֿאַ; ניין פֿון די עלף קאָנטראָלן אַרבעטן אָפֿליין; טעקעס בלײַבן אין בראַוזער.","tags":["זשורנאַליסטיק","קאָנטראָל","בילדער"]},"balanta":{"line":"פֿאַרגלײַכט AI־מאָדעלן בלינד: שטעלט אײַן ענטפֿערס פֿון צוויי ביז אַכט מאָדעלן אויף 92 פּראָמפּטן אויף ראָמעניש, ענגליש און אונגעריש, שטימט A אָדער B און קריגט אַן ראַנג מיט אינטערוואַלן. אַלפֿאַ; אַרבעט אָפֿלײַן.","detail":"בלינדע זײַט־בײַ־זײַט אויסוואַרטונג פֿון AI־מאָדעלן אויף רומעניש. איר קלעפּט אײַן יעדן מאָדעלס ענטפֿערס אַליין (גאָרנישט ווערט גערופֿן: קיין API־שליסלען, קיין קאָנטאָס), די אַפּ באַהאַלט די מאָדעל־נעמען אין די ענטפֿערס, פֿיקסירט די סדר פֿון אַ זוימען און פֿאַרצייכנט אײַער שטימע. דער ראַנג ניצט Bradley–Terry און Elo מיט 95%־bootstrap־אינטערוואַלן, פּלוס געווינס־ראַטע, פּאָזיציע־באַפֿאָרורטעילונג און קאָפּ־צו־קאָפּ־טאַבעלעס. שטימען און ענטפֿערס זענען אָפֿענע JSON Lines־טעקעס. מיט ווינציק שטימען אָדער פּראָמפּטן זאָגט דער ראַנג גאָרנישט אַלגעמיינס. אַלפֿאַ; דאַטן בלײַבן אין בראַוזער; קיין נאָכפֿאָלגן.","tags":["AI","אָפּשאַצונג"]},"calendarium":{"line":"שרײַבט אַן דאַטום אין איינעם פֿון עלף קאַלענדאַרן (גרעגאָריאַניש, יוליאַניש, ייִדיש, היזשרע, פּערסיש, כינעזיש, מאַיאַ, מאַרסיאַניש…) און זעט אין די אַנדערע, מיט חודש־אַנזיכט. אַלפֿאַ; אַרבעט אָפֿלײַן.","detail":"קאָנווערטירט דאַטומען צווישן עלף קאַלענדאַרן (גרעגאָריאַניש, יוליאַניש, רעוויזירט יוליאַניש, העברעיש, הידזשרי, פּערסיש, קאָפּטיש, עטיאָפּיש, כינעזיש, מײַאַ און דער Mars Sol Date), ווײַזט דעם יוליאַנישן טאָג, וואָכנטאָג און ISO־וואָך, און האָט אַן חודש־אָנזיכט מיט אַ צווייטן קאַלענדאַר אונטער יעדן טאָג. שליסט אײַן רומענישע נאָטיצן (אַלטער און נײַער סטיל, די איבערשטעלונג פֿון 1919, יום־טובֿ) און אַן אַטלאַס פֿון די קאַלענדאַרן, איין פּלאַגין פֿאַר יעדן קאַלענדאַר. ווערטן ווערן אויסגערעכנט, מיט געזאָגטע באַגרענעצונגען (דער הידזשרי־קאַלענדאַר איז דער טאַבולערער; געביטן זענען באַשיצט). אַלפֿאַ, אין 8 שפּראַכן, אַרבעט אָפֿליין; קיין נאָכפֿאָלגן.","tags":["קאַלענדאַרן","צײַט"]},"glosar":{"line":"אָפֿלײַן־ווערטערבוך פֿאַר אַראָמאַנישע, מעגלענאָ־ראָמאַנישע און ראָמאַנעס־שפּראַכן: זוכט אָן דיאַקריטישע צייכנס, זעט וואָס באַזישע ווערטער פֿעלן און לייגט צו ווערטער מיט קוואַל און סטיל. אַלפֿאַ.","detail":"ווערטערביכער פֿאַר מינאָריטעט־ און געפֿערדעטע שפּראַכן, געבויט דורך זייערע רעדער. זוכט אָן אַקצענטן, ווײַזט פֿאַרלעסלעכקייט (פּלאַן, מיט קוואַל, איבערגעקוקט), האָט אַ דעקונג־טאַבעלע פֿון 50 גרונט־באַגריפֿן, און לאָזט אײַך צולייגן ווערטער מיט אַ קוואַל, אַ ליצענץ און אַן אויפֿנאַמע (ביז 50 KB). עקספּאָרטירט TSV־ און Anki־טעקעס און אַ בײַטראָג־טעקע פֿאַרן פּראָיעקט. די אָנהייב־רשימות זענען קליין — צאָל־ווערטער און אַ ביסל ווערטער, יעדעס מיט אַ פֿאַרעפֿנטלעכטער קוואַל — און קיין רעדער האָט זיי נאָך נישט איבערגעקוקט. אַלפֿאַ; אַרבעט אָפֿליין; דאַטן בלײַבן אין בראַוזער ביז איר לאָדט זיי אַראָפּ.","tags":["שפּראַכן","ווערטערביכער"]},"graiul":{"line":"אָפֿלײַן־אַרכיוו פֿון ראָמענישן פֿאָלקלאָר (שפּריכווערטער, בשׁבֿועות, רעטענישן, קאָלינדעס) מיט קוואַל, געגנט און הסכּמה. הייבט זיך אָן מיט צען שפּריכווערטער; איר קענט צולייגן מער. אַלפֿאַ.","detail":"זוך אָן אַקצענטן, מיט פֿילטערס לויט טיפּ, קרײַז און פֿאַרלעסלעכקייט; אַ שפּריכווארט פֿון טאָג (דאָס זעלבע פֿאַר אַלעמען אויף אַ געוויסן דאַטום), אַ סכעמאַטישע קאַכל־מאַפּע פֿון 41 קרײַזן און Bucharest, און אַ צולייג־פֿאָרעם וואָס פֿאָדערט אַ קוואַל און, פֿאַר שפּרוכן און אַלץ וואָס איז געזאַמלט געוואָרן פֿון אַ מענטש, אַ הסכּמה. עקספּאָרטירט אַ בײַטראָג־טעקע און TSV. די אָנהייב־דאַטן זענען צען רומענישע שפּריכווערטער פֿון Wikiquote; קיין איינציקער איז נישט איבערגעקוקט געוואָרן דורך אַ פֿאָלקלאָריסט. אַלפֿאַ; אַרבעט אָפֿליין; דאַטן בלײַבן אין בראַוזער ביז איר לאָדט זיי אַראָפּ.","tags":["פֿאָלקלאָר","אַרכיוו"]},"indicativ-international":{"line":"טרענירט די פֿראַגעס פֿון דער ראַדיאָ־ליבהאָבער־פּרוּוו מיט אַ פֿינף־קעסטל־איבערחזרונג־פּלאַן און געצײַטיקטע פּראָבע־עקזאַמען; ימפּאָרטירט פֿראַגע־פּאַקעטן אין אַ געמיינזאַמען JSON־פֿאָרמאַט. 50 איבונג־פֿראַגעס אײַנגעשלאָסן; נישט קיין אָפֿיציעלע באַנק. אַלפֿאַ.","detail":"אַ טרענער און עקזאַמען־סימולאַטאָר פֿאַר פֿראַגעס פֿון ליבהאָבער־ראַדיאָ־ליצענצן, מיט אַ געמיינזאַמען פּעקל־פֿאָרמאַט, כּדי יעדע לאַנד זאָל קענען צולייגן איר אייגענע באַנק. „Train“ ווידערהאָלט ריכטיקע ענטפֿערס נאָך 1, 3, 7, 14 און 30 טעג און דערקלערט יעדן ענטפֿער מיט זײַן קוואַל; „Exam“ איז אַ טעסט מיט אַ צײַט־באַגרענעצונג און אַ דורכפֿאַל־גרענעץ; „Packs“ אימפּאָרטירט און קאָנטראָלירט פּעקלעך און מאַכט אַ באַקאַפּ פֿון אײַער פּראָגרעס. דער אײַנגעבויטער פּעקל האַלט 50 אָריגינעלע איבונג־פֿראַגעס געשריבן פֿאַר דעם פּראָיעקט — נישט קיין אָפֿיציעלע באַנק — און קיין לאַנד־פּעקל איז נאָך נישט אַרײַנגעשלאָסן. אַלפֿאַ; אַרבעט אָפֿליין; פּראָגרעס בלײַבט אין בראַוזער.","tags":["ראַדיאָ","עקזאַמען"]},"proiector-fara-frontiere":{"line":"די טעלעפֿאָנען אין קלאַס ווערן אַ געמיינזאַמער עקראַן, אָן סערווער און קאָנטעס: טײַמער, אַנקעטע, וויקטאָרינע, נאָטיצן און טאָוול; פּאַרן מיט QR־קאָד אָדער אײַנגעשטעלטן טעקסט אין דעם זעלבן נעץ. אַלפֿאַ; מיט ריאַלע טעלעפֿאָנען נאָך נישט געטעסט.","detail":"אַ געמיינזאַמער עקראַן פֿאַר דער קלאַס, אָן סערווער און אָן קאָנטאָ. דער לערער עפֿנט די זײַט בײַם פּראָיעקטאָר; יעדעס שילערס טעלעפֿאָן שליסט זיך אָן דורך אויסבײַטן אַ קאָד (QR־פֿריימס, אַ פֿאָטאָ פֿון דעם קאָד אָדער אײַנגעקלעפּטער טעקסט), ביז 30 טעלעפֿאָנען אויף אַמאָל. פֿינף אַקטיוויטעטן זענען אײַנגעשלאָסן: אַ אָפּציילונג־טײַמער, אַן אָפּשטימונג מיט לעבעדיקע בעלקן, אַ קוויז (פֿראַגעס פֿון אַ JSON־, פּשוט־טעקסט־ אָדער CSV־טעקע; דער ריכטיקער ענטפֿער בלײַבט אויפֿן פּראָיעקטאָר ביז ער ווערט אַנטפּלעקט; גיכקייט־בונוס און רעזולטאַט־טאַוולע), קלעפּ־נאָטיצן און אַ טאַוולע מיט איין קאָליר פֿאַר יעדן טעלעפֿאָן. רעזולטאַטן קען מען היטן ווי CSV, טעקסט אָדער PNG. יעדע אַקטיוויטעט לויפֿט אין אַן אײַזאָלירטן פֿריים מיט נאָר די דערלויבענישן וואָס זי דעקלאַרירט, און אַ נײַע אַקטיוויטעט איז איין דעסקריפּטאָר און איין סקריפּט. דער לערער קען שליסן אָדער אַראָפּנעמען אַ טעלעפֿאָן און ענדיקן די סעסיע; יעדער מכשיר קלײַבט זײַן אייגענע שפּראַך (אַכט) און אויסזען (טונקל, הויכער קאָנטראַסט, גרויסער טעקסט). עס אַרבעט אָפֿליין נאָכן עפֿענען און מען קען עס אינסטאַלירן. אַלפֿאַ: געטעסט אין Chromium מיט ריאַלע פֿאַרבינדונגען אויף איין מאַשין, נישט אויף ריאַלע טעלעפֿאָנען, אַנדערע בראַוזערס אָדער שול־נעצן. דאָס צוזאַמענפּאָרן פֿאָדערט דעם זעלבן לאָקאַלן נעץ (קיין רעלע), ווײַזט יעדן מכשירס IP־אַדרעס צום אַנדערן און באַשטעטיקט נישט ווער דער אַנדערער מכשיר איז. דער „Undava“־קוויז־פֿאָרמאַט ווערט נישט געשטיצט: קיין ספּעציפֿיקאַציע איז נישט געפֿונען געוואָרן.","tags":["קלאַס","פּראָיעקציע","וויקטאָרינע"]},"regula":{"line":"שפּילט פֿינף קלאַסישע שפּילן פֿאַר צוויי (מילן, alquerque, fanorona, mū tōrere, hnefatafl) קעגן אַ קאָמפּיוטער אָדער אַ פֿרײַנד; לייגט צו אײַער שפּיל ווי JSON. אַלפֿאַ; אַרבעט אָפֿלײַן.","detail":"איין כּללים־מאָטאָר פֿאַר טראַדיציאָנעלע ברעט־שפּילן: יעדעס שפּיל איז אַ JSON־טעקע, און דער כּללים־טעקסט אין אַכט שפּראַכן ווערט גענערירט פֿון די זעלבע דאַטן וואָס דער מאָטאָר שפּילט, אַזוי אַז טעקסט און שפּיל קענען זיך נישט סתּרן. יעדער צד קען זײַן אַ מענטש, אַ טראַפֿעוודיקער שפּילער אָדער דער קאָמפּיוטער אויף צוויי מדרגות; צוריקנעמען, איבערמאַכן, אַן עצה און אַ קאָפּירבאַרער צוג־פּראָטאָקאָל. איר קענט אײַנקלעפּן, פֿאַרבאַשטעטיקן און שפּילן אײַער אייגן שפּיל. די שפּילן זענען רעקאָנסטרוקציעס, נישט טורניר־כּללים, און יעדעס זאָגט ווי זיכער זײַנע כּללים זענען. אַלפֿאַ; אַרבעט אָפֿליין; קיין נאָכפֿאָלגן.","tags":["שפּילן","כּללים"]},"vietar-packs":{"line":"קוקט, ימפּאָרטירט, קאָנטראָלירט און שאַפֿט רעגיאָנאַלע מינים־פּאַקעטן פֿאַר VietAR: נעמען אין עטלעכע שפּראַכן, סימנים פֿון גיפֿטיקייט, ענלעכע מינים. פֿינף פּרויעקט־סטאַרט־פּאַקעטן מיט 71 מינים. אַלפֿאַ; אַרבעט אָפֿלײַן.","detail":"רעגיאָנאַלע מינים־פּעקלעך פֿאַר VietAR: נעמען אין עטלעכע שפּראַכן, אַ סם־סימן, געפֿערלעכע ענלעכע מינים, און אָרט פֿאַר ליצענצירטע פֿאָטאָס און קלאַנג־לינקס. בלעטערט און זוכט פֿינף אָנהייב־פּעקלעך (רומעניע: געוויקסן און שוועמלעך, פֿייגל, זויגטירן; בולגאַריע און מאָלדאָווע: סקעלעטן), אימפּאָרטירט אַ פּעקל, קאָנטראָלירט עס מיט די זעלבע כּללים ווי דער ריפּאָזיטאָריע, אָדער שאַפֿט איינעם פֿאַר אַ שול־קלאַס אָדער נאַטור־קלוב. די אָנהייב־פּעקלעך זענען פּלענער אָן פֿאָטאָס אָדער קלאַנגען, און „נישט מאַרקירט ווי סמיק“ מיינט קיינמאָל נישט עסבאַר אָדער זיכער. די VietAR־אַפּ קען נאָך נישט אימפּאָרטירן פּעקלעך. אַלפֿאַ; אַרבעט אָפֿליין.","tags":["נאַטור","מינים"]},"PatruZeci":{"line":"אילוסטרירטער אַנימאַציע־אַטלאַס פֿון WD-40־נוצן: גיידבוך מיט 147 קאַרטן און אָפֿיציעלע רשימה פֿון 1993 נוצן, יעדער מיט אַן אײגענער אַנימירטער סצענע. נישט אָפֿיציעל, אָפֿלײַן, אָן קאָנטאָ.","detail":"אַן אילוסטרירטער, אַנימירטער אַטלאַס פֿון WD-40־שפּריץ־באַניצונגען אין איין אָפֿליין־טעקע: אַ פֿירער פֿון 147 קאַרטלעך אין 14 קאַטעגאָריעס (מיט אַ ריזיקע־מדרגה און וואָס דער שפּריץ טוט), די אָפֿיציעלע „2000+ uses“־רשימה מיט 1993 אײַנטראָגן, און אַן אָפּטייל פֿון 25 צוגעגעבענע באַניצונגען, מיטען און ווארענונגען פֿון וועב־אַרטיקלען. 131 אַנימירטע סצענע־וואַריאַנטן, פֿילטערס לויט קאַטעגאָריע און פֿונקציע, אינטערפֿייס אין 8 שפּראַכן. אומאָפֿיציעלע, אומאָפּהענגיקע אַפּ.","tags":["WD-40","טו עס אַלײן"]},"ODISEEA":{"line":"דאָקומענטאַר־פֿילם פֿון בערך 4,5 מינוט וועגן וויאָדזשער 1 און 2 אין איין HTML־טעקע: סצענעס געשאַפֿן אויפֿן גראַפֿיק־קאַרטל, עקספּאָרט פֿאַר 2D און 3D VR־ברילן, אין 8 שפּראַכן.","detail":"אַ דאָקומענטאַר פֿון בײַ 4.5 מינוט וועגן די זאָנדעס Voyager 1 און 2, אין איין HTML־טעקע וואָס לויפֿט לאָקאַל אין בראַוזער, אָן סערווער און אָן אינסטאַלאַציע. פּראָצעדוראַלע סצענעס גענערירט אויפֿן גראַפֿיק־קאַרטל (WebGL): פּלאַנעטן, זאָנדע, ראַקעט, DSN־אַנטענע, די Golden Record, די העליאָספֿער, דער Pale Blue Dot. עפֿנטלעכע NASA/JPL־ און Wikimedia Commons־בילדער, אָדער אײַער אייגן בילד פֿאַר יעדע סצענע. עקספּאָרט אין 2D, האַלב (1920×1080) און פֿול (3840×1080) 3D זײַט־בײַ־זײַט, און אַ טעלעפֿאָן־אופֿן פֿאַר VR־ברילן ווי VR BOX; אַמביענט־מוזיק גענערירט אין בראַוזער, אַפּציאָנעלער דערציילער. אינטערפֿייס, דערציילונג, אונטערשריפֿטן און קרעדיטן אין 8 שפּראַכן.","tags":["וויאָדזשער","דאָקומענטאַר"]},"EXIF-CURAT":{"line":"אין אַנטוויקלונג: געצייג אין Rust מיט זיכערע פּאַרסערס צו קוקן און רײניקן באַהאַלטענע דאַטן אין טעקעס (בילדער, PDF, Office, ווידעאָ: EXIF, GPS, XMP). ביז איצט נאָר אַ פּרע־אַלפֿאַ סקעלעט.","detail":"אין אַרבעט: אַ געצייג צו זען און אַראָפּנעמען די באַהאַלטענע דאַטן אין טעקעס (בילדער, PDF, Office, וידעאָ: EXIF, GPS, XMP), מיט זכּרון־זיכערע פּאַרסערס, געשריבן אין Rust. ביז אַצונד נאָר אַ פּרע־אַלפֿאַ־סקעלעט.","tags":["מעטאַדאַטן","פּריוואַטקייט"]},"PORUMBEL":{"line":"טראָגט אויטאָמאַטיש איבער בילדער פֿון Open Camera אויפֿן טעלעפֿאָן אין אַ טעקע אויפֿן קאָמפּיוטער, איין טעקע פֿאַר יעדע סעסיע, און עפֿנט זיי אין LegatorOCR. אָן קאָנטאָ, אָן וואָלקן, אָן דריטע־צד crate׳ס.","detail":"אַ קליין פּראָגראַם געשריבן אין Rust, אָן דריט־צד־קרייטס (Windows, macOS, Linux), וואָס ברענגט די פֿאָטאָס וואָס איר מאַכט מיט Open Camera אויף אײַער קאָמפּיוטער: איבער Wi-Fi (אַ אַרויפֿלאָד־זײַט אָדער WebDAV, מיט אַ QR־קאָד), איבער ADB (USB אָדער Wi-Fi) אָדער פֿון אַ סינכראָניזירטער פּאַפּקע (Syncthing אאַז״וו). ער סאָרטירט די פֿאָטאָס אין איין פּאַפּקע פֿאַר יעדע פֿאָטאָ־סעסיע און עפֿנט יעדע פֿאַרטיקע סעסיע אין LegatorOCR (שפּאַלטן, אויסגלײַכן, שנײַדן, PDF מיט OCR). אַ לאָקאַלער קאָנטראָל־טאַוולע און אַ „porumbel doctor“־באַפֿעל פֿאַר דיאַגנאָזע; גאָרנישט פֿאַרלאָזט אײַער נעץ. ווערסיע 0.x; MIT־ליצענץ.","tags":["בילדער","איבערטראָג"]},"colibri-companion":{"line":"פֿרײַנטלעכע דעסקטאָפּ־אַפּליקאַציע פֿאַר דעם ערטלעכן colibri־אינפֿערענץ־מאָטאָר: קלײַבט אַ מאָדעל וואָס פּאַסט צו אײַער קאָמפּיוטער, לאָדט אַראָפּ מיט איין קליק און רעדט מיט אים. אָן קאָנטאָ, אָן וואָלקן־סערוויס.","detail":"אַן דעסקטאַפּ־אַפּ געשריבן אין Rust פֿאַר colibri (JustVugg/colibri): זי געפֿינט Python און colibri, ווײַזט נאָר די מאָדעלן וואָס פּאַסן אין אײַער קאָמפּיוטערס זכּרון, לאָדט זיי אַראָפּ מיט פּויזע און פֿאָרזעצן, שטאַרט דעם לאָקאַלן סערווער און עפֿנט דאָס שמועס (סטרימענדיקע ענטפֿערס, Markdown, געהיטענע שמועסן, זוך, לאָקאַלע דאָקומענטן און MCP־געצייגן מיט באַשטעטיקונג בײַ יעדן רוף). דער Resources־פּאַנעל ווײַזט פּראָצעסאָר, זכּרון, גראַפֿיק־קאַרטל און אָפֿענע פֿאַרבינדונגען. Windows, macOS, Linux; אינטערפֿייס אין 8 שפּראַכן; Apache-2.0־ליצענץ.","tags":["ערטלעכער AI","דעסקטאָפּ"]},"CartaColibri":{"line":"ערטלעכע AI־ביבליאָטעק אויפֿן Colibrì־מאָטאָר: אינדעקסירט די טעקעס וואָס איר קלײַבט, זוכט תּיכּף און בעט דעם ערטלעכן מאָדעל צו אָפּקורצן, ארויסנעמען דאַטן אָדער סינטעזירן, אַלע מאָל מיט דער קוואַל־טעקע. גאָרנישט פֿאַרלאָזט אײַער קאָמפּיוטער.","detail":"אַ פּראָגראַם געשריבן אין Rust, מיט אַ לאָקאַלער זײַט (127.0.0.1) און אַ באַפֿעל־שורה. זי אינדעקסירט די פּאַפּקעס וואָס איר קלײַבט (אָריגינאַלן ווערן נאָר געלייענט, קיינמאָל נישט געענדערט), זוכט אין פֿולטעקסט (ווערטער, „פֿראַזעס“, פּרעפֿיקס*, AND/OR/NOT, פֿילטערס לויט טיפּ, גרייס, אָרט) און גרופּירט טעקעס. אַ לאָקאַלער Colibrì־מאָדעל מאַכט אַ סך־הכּל, עקסטראַהירט (טאַבעלע אָדער JSON, „NOT FOUND“ אַנשטאָט טרעפֿענישן), סינטעזירט אָדער פֿאַרגלײַכט, תּמיד מיט צוגעשטעלטע קוואַלן [S1], [S2] און אַן grounding־אָפּשאַצונג. עס האָט אויך דעם קליינעם web-grab־בראַוזער, אַ בלויז־לייענען MCP־סערווער, אימפּאָרטן (בוקמאַרקס, Obsidian, Zotero, RSS) און אַ קאָנטראָל פֿון אײַער אייגענעם טעקסט קעגן דער ביבליאָטעק. קיין קאָנטאָ, קיין טעלעמעטריע; אינטערפֿייס אין 8 שפּראַכן; אַלפֿאַ־ווערסיע 0.2; MIT־ליצענץ.","tags":["ערטלעכער AI","ביבליאָטעק"]},"PolyTabletop":{"line":"240 טיש־שפּילן קעגן אַ קאָמפּיוטער אין טערמינאַל אָדער גראַפֿישן פֿענצטער, און צוויי־שפּילער אויף דער זעלבער קלאַוויאַטור אָדער נעץ. געשריבן אין Rust; דער מאָטאָר און די שפּילן האָבן קיין דרויסנדיקע אָפּהענגיקייטן.","detail":"אַ clean-room זאַמלונג פֿון טישפּלאַטע־שפּילן געשריבן אין Rust: 240 שפּילבאַרע שפּילן קעגן דעם קאָמפּיוטער, אין דער טערמינאַל אָדער אין אַ גראַפֿישן פֿענצטער, פּלוס hot-seat און צוויי־שפּילער־נעץ־שפּיל. אַבסטראַקטע קלאַסיקער, קאַרטן־ און קוביה־שפּילן, אָריגינעלע וואַריאַנטן פֿון מאָדערנע מעכאַניקן אונטער אייגענע נעמען, קאָאָפּעראַטיווע שפּילן מיט אַן AI־פּאַרטנער, באַהאַלטענע־ראָלעס־שפּילן, פּאַרטיי־ און וואָרט־שפּילן; דער קאַטאַלאָג האָט 1200 אײַנטראָגן, מיט אַ ראָלן־שפּיל־געצײַג־קעסטל (קוביעס, בלעטער, דזשאַנגל־גענערייטאָר, שלאַכט־סימולאַטאָר). AI־קעגנער (alpha-beta, MCTS), AI־קעגן־AI־אַרענע, טראַנסקריפּטן און ווידערשפּילונגען. אינטערפֿייס אין 8 שפּראַכן; ווערסיע 0.9; MIT־ אָדער Apache-2.0־ליצענץ.","tags":["טיש־שפּילן","Rust"]},"STRAJA":{"line":"שילד קעגן AI־אַגענטן וואָס לייענען אײַער טעלעפֿאָן: ווײַזט וועלכע אַפּליקאַציעס קענען לייענען אײַערע נאָטיפֿיקאַציעס, עקראַן, בילדער און SMS, ווארענט ווען אַן נײַע באַקומט צוטריט, און פֿירט צו אײַנשטעלונג וווּ איר קענט צוריקרופֿן די דערלויבעניש. אָן קאָנטאָ, אָן INTERNET־דערלויבעניש.","detail":"אַן אַפּ פֿאַר Android (APK) און iPhone (אומאונטערגעשריבענער IPA). אויף Android ליסטעט זי די אַפּס מיט צוטריט צו נאָטיפֿיקאַציעס, אַקסעסיביליטי־סערוויסעס, דער אַסיסטענט־ראָלע און דערלויבענישן פֿאַר מעדיע און SMS, מיט אַ ריזיקע־אָפּשאַצונג פֿאַר יעדע אַפּ און פֿאַר דעם גאַנצן טעלעפֿאָן; אַן פּעריאָדישער מאָניטאָר פֿאַרגלײַכט דעם טעלעפֿאָן מיט אַ באַזע־ליניע און מעלדט אײַך וועגן יעדן נײַעם צוטריט. זי עפֿנט די גענויע סיסטעם־איינשטעל־זײַט צו אָפּרופֿן אַ צוטריט און ענדערט קיינמאָל גאָרנישט שטיל. צײַטווײַליקער צוטריט מיט אַן דערמאָנונג, און אַ 12־פּונקטיקער שוץ־פֿירער. אויף iPhone איז נישטאָ קיין אויעדיט (iOS באַהאַלט די דערלויבענישן פֿון אַנדערע אַפּס), נאָר דער פֿירער, אַ מאַנועלער רעגיסטער און דערמאָנונגען. זי קען נישט אָפּשטעלן קיין אַגענט. קיין INTERNET־דערלויבעניש, קיין באַקאַפּ; 8 שפּראַכן; ווערסיע 1.0; MIT־ליצענץ.","tags":["פּריוואַטקייט","טעלעפֿאָן"]},"CUPLAJ":{"line":"געמיינזאַמע ליניע־טעלעפֿאָניע פֿאַר אימערסיווען טעאַטער: אַ פֿלאָט פֿון געווײנלעכע Android־טעלעפֿאָנען ווערט אַ פּריוואַטע צענטראַלע מיט אָרטיק Wi-Fi; אָן וואָלקן, אָן קאָנטעס, אָן רעקלאַמע. כאַראַקטעריסטישע פֿונקציע איז „cuplaj“: די געמיינזאַמע ליניע פֿון סטאַציאָנאַרע טעלעפֿאָנען פֿון די 1980ער ביז בערך 2006.","detail":"אַן Android־אַפּ (APK) און אַן iPhone/iPad־אַפּ (אומאונטערגעשריבענער IPA). אָרגאַניזאַטאָרן און אַקטיאָרן רעדן מיט צוקוקער איבער דעם לאָקאַלן Wi-Fi; איין טעלעפֿאָן (דער קאָנטראָל) איז די צענטראַלע. זעקס טעלעפֿאָן־תּקופֿות (1985 דרייסקיבע, 1995 קלאַוויאַטור, 2003 מאָביל, 2025 סמאַרטפֿאָן, 2045 טראָגבאַרע, 2080 געמיינזאַמער מוח), די פּאַרטיי־ליניע וווּ צוויי אַבאָנענטן טיילן איין ליניע, ריאַלע רופֿן, דריק־צו־רעדן עפֿנטלעכע אָנזאָג, אַ הינטער־די־קוליסן־קאַנאַל, סיגנאַלן (פֿולער־עקראַן־טעקסט, וויבראַציע, קלינגען, בליץ, גערעדטער קול, פֿאַנטאָם־רוף) און אַ סקריפּט מיט GO און PLAY. קיין אינפֿראַסטרוקטור, אַפּציאָנעלער AES-128-GCM־נעץ־שליסל, דירעקטע P2P־רופֿן. קיין אַנאַליטיק, קיין סערווערס, קיין קאָנטאָס. 8 שפּראַכן; ווערסיע 1.10; MIT־ליצענץ.","tags":["אימערסיווער טעאַטער","טעלעפֿאָניע"]},"LUSTRUM":{"line":"נעמט צוריק דעם אָרט אויף אײַער טעלעפֿאָן: געפֿינט איבעריקע טעקעס, דופּליקאַטן, ענלעכע בילדער און איבערבלײַבענישן פֿון אַפּליקאַציעס און רײניקט זיי נאָר מיט אײַער הסכּמה. האָט קיין INTERNET־דערלויבעניש נישט, דעריבער קען פֿיזיש גאָרנישט אָפּשיקן.","detail":"אַן Android־אַפּ (Kotlin). אָפּשפּײַכער לויט טעקע־טיפּ, גרויסע, אַלטע און מיסט־טעקעס, גענויע דופּליקאַטן (גרייס, שנעלער פֿינגערפּרינט, דערנאָך SHA-256), ענלעכע פֿאָטאָס (פּערצעפּטועלע האַשינג), רעשטלעך פֿון אָפּגעמעקטע אַפּס, JPEG־קאָמפּרעסיע, קעשעס, פֿאַרשמירטע און טונקעלע פֿאָטאָס, אַ Swiper (לינקס = אויסמעקן, רעכטס = האַלטן), פּלאַנירטע רײניקונג און אַ 30־טאָגיקער LUSTRUM־מיסט־קאָרב פֿאַר צוריקנעמען. קיין INTERNET־דערלויבעניש: גאָרנישט פֿאַרלאָזט דעם טעלעפֿאָן. קיין root־כּישוף: Android 11+ האַלט יעדע געוויינטלעכע אַפּ אַרויס פֿון די דאַטן־פּאַפּקעס פֿון אַנדערע אַפּס. 8 שפּראַכן (מאַשין־איבערזעצונגען); בעטאַ־ווערסיע 0.8; MIT־ליצענץ.","tags":["טעלעפֿאָן־רײניקער","Android"]},"STENOGRAMA":{"line":"טראַנסקריפּציע פֿון לאַנגן אויַדיאָ גלײַך אין בראַוזער מיט ערטלעכן Whisper: איין HTML־טעקע, אָן קאָנטאָ, אָן סערווער, אָן וואַסערצייכן. אײַער אויַדיאָ פֿאַרלאָזט קיינמאָל נישט דעם מכשיר; נאָר דער Whisper־מאָדעל ווערט אַראָפּגעלאָדן, איין מאָל.","detail":"לייענט MP3 און WAV אין שטיקער (דעריבער איז די לענג נישט באַגרענעצט דורך זכּרון); אַנדערע פֿאָרמאַטן (M4A, OGG/Opus, MP4, FLAC) ווערן גאַנץ דעקאָדירט. יעדער שטיק ווערט געשניטן בײַ אַ פּויזע כּדי ווערטער זאָלן נישט ווערן צעשפּאָלטן; פּראָגרעס ווערט געהיט, אַזוי אַז איר קענט אָפּשטעלן און פֿאָרזעצן. רעדאַקטאָר אין דער זײַט (קליקט אויף אַ צײַט צו הערן דעם אָרט), אַראָפּנעמען פֿון Whisper־ס טיפּישע גײַסט־פֿראַזעס, עקספּאָרט אין .txt, .srt, .vtt, .docx אָדער אין דער צווישן־שפּײַכער. ניצט WebGPU ווען עס איז פֿאַראַן, אַנדערש דעם פּראָצעסאָר (WASM). אינסטאַלירבאַרער PWA; דער מאָדעל בלײַבט אין קעש נאָכן ערשטן אַראָפּלאָד. די ביבליאָטעק ווערט געלאָדן פֿון jsDelivr בײַם ערשטן טראַנסקריבירן, קאָנטראָלירט מיט SHA-384. אינטערפֿייס אין 7 שפּראַכן; MIT־ליצענץ.","tags":["טראַנסקריפּציע","אויַדיאָ"]},"GERMEN":{"line":"טרענירט אַ קליינעם שפּראַך־מאָדעל פֿון נול אין ריינעם Rust אויף אַ געווײנלעכן פּראָצעסאָר: אָן Python, אָן CUDA, אָן קאָנטאָ, אָן נעץ־צוטריט, אָן טעלעמעטריע. איין בינאַרע טעקע, איין טעקסט־טעקע, איין קאָמאַנדע.","detail":"אַ Rust־פּראָגראַם (אויף Burn, מיט זײַן פּורן־Rust CPU־באַקענד) וואָס טרענירט אַ GPT־סטיל נעץ איבער בײַטן אָדער איבער אַ BPE־וואָקאַבולאַר געלערנט פֿון אײַער אייגענעם טעקסט, דערנאָך גענערירט טעקסט פֿון דעם טרענירטן מאָדעל. GERMEN Studio: אַ לאָקאַלער פֿענצטער (127.0.0.1) מיט דער לאָס־קרומע, דער גיכקייט און טעקסט־מוסטערס, אין 8 שפּראַכן. באַפֿעלן צו מעסטן די גיכקייט פֿון אײַער קאָמפּיוטער און צו קאָנטראָלירן און פֿאַרריכטן מאָדעל־טעקעס. עס איז אַ װערקשטאַט פֿאַרן לערנען און עקספּערימענטירן, נישט קיין שמועס־באָט־פֿאַבריק: אַ מאָדעל פֿון 1–25 מיליאָן פּאַראַמעטערס לערנט די פֿאָרעם פֿון אַ טעקסט, נישט וועלט־וויסן. קיין GPU, קיין געמישטע פּרעציזיע. ווערסיע 0.6; MIT־ליצענץ.","tags":["ערטלעכער AI","Rust"]},"CUANTOR":{"line":"סימולאַטאָר פֿון אַ קוואַנטן־קאָמפּיוטער פֿאַר אײַער דעסקטאָפּ, פֿון 5 ביז 1000 קיוביטן, מיט אַן IBM Quantum Composer־סטיל אינטערפֿייס. גענויע מאַטעמאַטיק, אָבער נישט ריאַלע קוואַנטן־אַפּאַראַטור.","detail":"אַ Rust־פּראָגראַם אין פֿיר טיילן (קערן, פֿענצטער, באַפֿעל־שורה, IBM־לינק) פֿאַר Windows, macOS און Linux. אַ צייכן־ברעט ווי IBM־ס Composer: לייגט קאָלירטע טויערן אויף ליניעס (קוביטן) און קוקט ווי בעלקן און אַ ספֿערע ווײַזן דעם רעזולטאַט, בעת אַ טעקסט־פּאַנעל שרײַבט דעם זעלבן קרײַז לעבעדיק אין OpenQASM און Qiskit. דרײַ רעכענער: איינער וואָס געדענקט יעדע צאָל (ביז 28 קוביטן), איינער זייער שנעל פֿאַר פּשוטע טויערן (ביז 4096) און איינער פֿאַר קרײַזן מיט ווינציק צווײַגן. מעסטן, צוריקשטעלן און if אין מיטן לויף, אײַערע אייגענע טויערן, סימולירטער ראַש, רעזולטאַטן וואָס מען קען איבערחזרן מיט אַ זוימען. עס לייענט OpenQASM 2.0 און 3.0; איר קענט עפֿענען דעם קרײַז אין IBM Composer אָדער שיקן אים צו אַן אמתער IBM־מאַשין מיט אײַער אייגענעם קאָנטאָ־שליסל (נישט באַשטעטיקט אויף ריאַלער IBM־הארדוואַרג). אינטערפֿייס אין 8 שפּראַכן; ווערסיע 0.2.","tags":["קוואַנטן־קאָמפּיוטער","סימולאַטאָר"]},"ERATA":{"line":"אַ בראַוזער־קאָרעקטאָר וואָס קאָנטראָלירט רעכטשרײַבונג, גראַמאַטיק, אינטערפּונקציע און טיפּאָגראַפֿיע גלײַך אויף אײַער קאָמפּיוטער: קיין קאָנטאָ, קיין סערווער, קיין טעלעמעטריע. אַם טיפֿסטן פֿאַר רומעניש.","detail":"אַן ערווײַטערונג פֿאַר Chromium און Firefox (Safari־ווערסיע נישט געטעסט), געשריבן פֿון אָנהייב אָן קיין קאָד, כּללים אָדער דאַטן פֿון LanguageTool אָדער פֿון קיין אַנדער קאָנטראָלער. זי אַרבעט אין textarea־, input־ און contenteditable־פֿעלדער און צייכנט אירע אונטערשטרײַכונגען אָן צו ענדערן די זײַט. זי דערקענט די שפּראַך פֿאַר יעדן אָפּשניט, שטעלט צוריק דיאַקריטישע צייכנס (ro, fr, es, pt) נאָר ווו די פֿאַרריכטונג איז איינדײַטיק, און האָט טיפֿע רומענישע כּללים (קאָמע־אונטן ș/ț, „să/sa“, „într-un“, די קאָמע פֿאַר „dar/însă“). פּערזענלעכער ווערטערבוך, אייגענע כּללים, שאַלטער פּער זײַט, אימפּאָרט פֿון Hunspell־ווערטערביכער. אַפּציאָנעלע איבערשרײַבונג דורך אַ לאָקאַלן מאָדעל (נאָר localhost, אויסגעשאַלטן סטאַנדאַרטמעסיק). אינטערפֿייס אין 25 שפּראַכן. ווערסיע 0.4; MIT־ליצענץ.","tags":["קאָרעקטאָר","ערווײַטערונג"]}});
